// generated from DEVLOG.md by tools/devlog.py. In-game DEVLOG (tabs of fold-open entries) and CREDITS text.
export const DEVLOG = [["h1","2DISO SHIFT - devlog"],"",["p","A GitHub Game Off 2026 entry (theme: SHIFT). Designed and directed by Benjamin"],["p+","Campbell (BDC / GRiDDiM), built with Claude as the programmer. Every line of art and"],["p+","every sound is generated by code in this repo."],"",["h2","Backstory - how we make games"],"",["p","2DISO SHIFT was not built from a standing start. It sits on top of a way of working"],["p+","that BDC has been putting together all year."],"",["h3","The Griddim bootstrap"],["p","Griddim is a small network of sites that all share one shell. The rule for the shell"],["p+","is written down as a standard called the bootstrap, and it fits in one line:"],"",["p","Modules own screens. Agents operate on screens."],"",["p","Every site on the network has the same seven parts: a global header, a site header,"],["p+","a left bar of modules, a workspace that shows the active module, a right bar of"],["p+","agents, a site ticker and a global footer. A new site starts from one sentence"],["p+","('integrate this domain into the network, concept: ...') and the bootstrap fills in"],["p+","the rest, so nobody has to explain the architecture twice, to a person or to a"],["p+","model."],"",["h3","ArcadeGridz: the site and the app"],["p","ArcadeGridz is the arcade built on that shell. A game there is a module that mounts"],["p+","into the workspace through a small contract:"],"",["b","one mount function that hands back pause, resume and destroy handles"],["b","a shared controller layer, so a game listens for a handful of keys and every pad"],["b+","just works"],["b","a system menu on Start + Select, the same in every game"],["b","an agent panel on the right that shows live stats and Pause / Idle buttons"],["b","shared leaderboards, with runs tagged verified, assisted or cheater"],"",["p","There is also a native Windows launcher, the ag app. It syncs its catalog from the"],["p+","site, so adding a game to the site adds it to the app with no app update."],"",["p","A game counts as ready when it plays on keyboard, controller, phone and tablet, has"],["p+","its own menus with a real exit, pauses itself when it loses focus, and has an idle"],["p+","mode. Ready games are tagged BETA. Most of the catalog began as BDC's old GameMaker"],["p+","projects, rebuilt with the original source as reference rather than as a blueprint."],"",["p","The house rules for game code came out of that work, and this game follows them: the"],["p+","simulation is pure and seeded with a fixed 60 Hz step, players are an array even"],["p+","when there is one, and all input passes through one object per player. That is why"],["p+","the same code can run the title demo, idle mode, a headless test and, later,"],["p+","multiplayer."],"",["p","2DISO SHIFT is a standalone game first. The jam build runs from a single HTML page."],["p+","A thin adapter file is all that connects it to ArcadeGridz."],"",["h3","Different AI models for different jobs"],["p","BDC directs and the models build. Different models have ended up with different"],["p+","jobs:"],"",["b","ChatGPT and Codex built the original network shell, the first version of the"],["b+","arcade site and the on-site agents, and started the Windows launcher."],["b","Claude builds and maintains the games, and took over the launcher. This game was"],["b+","scoped in a first pass with one Claude model and built with a newer one."],["b","Small local models run the on-site agents day to day, with the larger models as"],["b+","a fallback."],["b","An autopilot inside the game is the tester. It plays every level headless after"],["b+","each change."],"",["p","What makes this work is written handoff. Every session ends with notes on what"],["p+","changed, what version is live and how to roll it back, so the next model, or the"],["p+","next session, starts from facts instead of guesses."],"",["p","BDC's side is the part a model cannot do: deciding what the game is, playing it, and"],["p+","saying what feels wrong. Most of the prompts quoted below are one or two lines long."],"",["h2","Day 1 - Wed 11 Nov 2026"],"",["h3","1. The idea"],["q","'what do you think about this game jam? can we make a revision of 2diso called"],["q+","2diso -shift- for this?'"],"",["p","The original 2DISO flipped between a 2D and an isometric view on a timer. The jam"],["p+","theme was SHIFT, so the fit was obvious. Two decisions came out of the first"],["p+","exchange:"],"",["q","'i would want a brand new game ... not just 2diso reskinned or renamed. and"],["q+","yes shifting between views with an action instead of timer was what i was"],["q+","thinking too.'"],"",["b","Checked the jam rules: source must be public on GitHub, existing code and AI"],["b+","help are allowed, but the game should be made for the jam."],["b","Created the public repo and pushed a README and MIT license."],"",["h3","2. The design prompt"],["q","'i also want it to shift between an over the shoulder view ... and a birds eye"],["q+","vertical rail view ... so thats 4 different views to shift between.'"],"",["p","This one message set most of the game: four views, a Griddim / ArcadeGridz splash"],["p+","and a ship swoop into the title, neon wireframe arcade art ('that way you dont have"],["p+","to generate sprites'), forced reasons to change view, hidden warps to bonus levels,"],["p+","the planet order (Earth, Mars, Jupiter, Planet X), an upgrade bar where each pickup"],["p+","moves a highlight and you choose when to spend it, drones that survive death, and a"],["p+","random god mode drop."],"",["p","Follow-ups locked the controls:"],["q","'shift should be controlled by L and R buttons. you kind of barrel roll into"],["q+","the views.'"],["q","'A can shoot. Y is bombs. X modifies drone behavior.'"],["q","'use select then to pick the upgrades and put a map menu item in the pause"],["q+","menu instead'"],"",["h3","3. The core rule"],["p","The design problem was making four views matter. The answer became the whole game:"],"",["p","What a view flattens does not exist for collisions."],"",["b","SIDE ignores left/right: a full-height skyscraper is a wall, a deck is something"],["b+","to duck."],["b","TOP ignores altitude: a deck is a wall, a skyscraper is something to steer"],["b+","round."],["b","ISO and CHASE keep all three axes: a wall with one hole needs them."],"",["p","One collision function with a per-view axis mask gave every obstacle a different"],["p+","meaning in every view, with no special cases."],"",["h3","4. Build order, first pass"],["b","1. font.js: a stroke font drawn as line segments, so there are no font files."],["b","2. game.js: pure seeded simulation at a fixed 60 Hz, players as an array, no"],["b+","DOM."],["b","3. An autopilot that plans against predicted obstacle positions. It runs Idle"],["b+","Mode and the title demo, and it plays every level headless as the test suite."],["b","4. render.js: four projections of the same 3D world, blended with a 360 degree"],["b+","roll for the shift."],["b","5. audio.js: all sound synthesised with Web Audio."],["b","6. ui.js: keyboard, controller and touch input, intro, menus, HUD, saves."],"",["p","Bugs worth remembering:"],["b","The autopilot flew into walls because it assumed it would travel in a straight"],["b+","line to its target, while the ship really moves at full speed on both axes at"],["b+","once. Predicting per axis fixed it."],["b","Key taps shorter than one frame were lost. Input now latches a press until it"],["b+","has been read."],"",["h3","5. Sound and story"],["q","'dont forget high score and combo systems, floating combat text, announcer"],["q+","voiceover, fanfare for pickups and things, a toast upon level completion,"],["q+","liquid dnb music, lofi during menus ... storyline about defending earth from a"],["q+","cosmic shift'"],"",["b","Liquid drum and bass in flight, lo-fi on the menus, a darker roller for bosses,"],["b+","all sequenced in code."],["b","Announcer through the browser's speech voice."],["b","Story: a rift from Planet X is folding reality one world at a time."],"",["p","The Earth demo went live on ArcadeGridz the same morning."],"",["h3","6. First playtest, second pass"],["q","'very cool ... in many ways its better than our original 2diso. it could use"],["q+","some tweaks'"],"",["p","The feedback list, and what changed:"],["b","'weapon upgrades are a little boring ... add wave weapon and a snaking lightning"],["b+","thing': SPEED left the bar. New bar: DRONE, SPREAD, LASER, WAVE, BOLT, MISSILE,"],["b+","SHIELD, ???. Each weapon has named tiers. BOLT snakes round the screen and then"],["b+","homes in."],["b","'the starting weapon should shoot a bit slower': every weapon starts slow and"],["b+","speeds up with its own level."],["b","'god mode should do that super hyper beam thing': god mode fires a rainbow hyper"],["b+","beam, maxes every weapon and fills out five drones the borrowed drones leave"],["b+","when it ends."],["b","'tap it and it cycles between slow speed, default speed, and thrusted speed': B"],["b+","is now a three-speed gear, and SLOW is the default."],["b","'it should give you a little more time to shift': the world slows while you"],["b+","roll, the roll is quicker, hints come earlier."],["b","'walls that spawn during the first boss fight need more gridlines': boss sheets"],["b+","are dense grids, the safe gap is framed in green, and they charge for longer."],["b","'add a altitude bar': left edge of the HUD, with the blocked heights ahead in"],["b+","red and the way through in green."],["b","'the warp needs to be more hidden': each warp can only be reached from one view,"],["b+","and now leads somewhere."],["b","'do all the levels including bonus levels ... unique enemies/obstacles/bosses':"],["b+","Mars (geysers, fire arcs, magma worms, alien stone heads, THE COLOSSUS), Jupiter"],["b+","(lightning chains, storm walls, wraiths, THE EYE), Planet X (tentacles,"],["b+","membranes, spores, THE SHIFTER), and bonus stages on the Moon, the Sun, the"],["b+","Asteroid Belt and Pluto."],["b","'the hyperspace segway ... should swap through all the views': every level opens"],["b+","by rolling through TOP, CHASE and ISO before handing over in SIDE."],["b","'more neon tube light glows': every line is drawn as a tube: wide halo, glow,"],["b+","bright core."],["b","Level select from the solar map, for testing."],"",["h3","7. Second playtest, quick fixes"],["q","'you made the walls that spawn during first boss actually harder to see not"],["q+","easier'"],"",["p","True. The new boss walls only drew their top and bottom faces, and in the 2D side"],["p+","view those are edge-on, so each wall collapsed into one line. Every face is now"],["p+","cross-hatched and the gap is boxed in green with chevrons."],"",["q","'mars boss should be more like an alien easter island type statue thing ..."],["q+","with smaller heads scattered throughout the level as enemies'"],"",["b","The Mars boss is now THE COLOSSUS, a giant alien stone head rising out of the"],["b+","ground. Its attacks: eruptions under you, a rising lava tide and falling ash,"],["b+","then rings of fire."],["b","Smaller stone heads run through the level: sentinels planted in the ground that"],["b+","lob fire, floating heads that stare you down, and statue pillars to weave"],["b+","between."],["b","Sun bonus: the shadow lane is a dense blue hatch with bright rails, the screen"],["b+","glows hotter as you cook, and the flares are fans of wavy tendrils."],["b","BOLT has a much longer lightning tail."],"",["h3","8. Solid shapes and the arenas"],["q","'add textures/gradient fills / shading / shadows to obstacles so we can see if"],["q+","it looks better or worse'"],"",["b","Obstacles can be drawn solid: dark shaded faces, a ground shadow, and the lines"],["b+","behind them hidden so the scene reads cleanly. It is an option (SOLID OBSTACLES)"],["b+","so both looks can be compared."],"",["q","'can we weave in an arena between levels that you have to clear a few waves in"],["q+","... that would match the theme of the level you just cleared'"],"",["b","After every boss there is now a bonus arena: GRID ZERO, THE CRUCIBLE, EYE OF THE"],["b+","STORM and THE HEART. Free movement inside a walled grid, auto-aim at the nearest"],["b+","target, five waves and a champion."],["b","SHIFT still matters: L/R flips the arena between TOP and ISO, and the white"],["b+","enemies can only be hit in ISO."],["b","Each arena carries its planet's hazard (geysers on Mars, lightning on Jupiter,"],["b+","and so on). Losing your shield ends the bonus without costing a life."],"",["h3","9. The 'make it more impressive' pass"],["q","'do you have any other suggestions for improvements or features for the game"],["q+","to make it more impressive?' ... 'ok do all that stuff.'"],"",["p","Nine ideas went on the list and all nine went in, plus one more from Benjamin."],"",["b","Perfect Shift. Roll out of the way of something that was about to hit you and"],["b+","the fold bites back: a shockwave, a few seconds of overdrive and a score bonus."],["b+","The theme is now the skill."],["b","Boss finishers. A dying boss comes apart in slow motion while the camera rolls"],["b+","through all four views."],["b","Twin-stick arenas. Right stick or mouse aims in the arenas. Auto-aim stays as"],["b+","the fallback, so a pad without sticks still works."],["b","A track per planet. Earth keeps the liquid roller, Mars gets a heavy half-time"],["b+","stomp, Jupiter fast arpeggios, Planet X a detuned whole-tone crawl, plus arena"],["b+","and bonus tracks. All still synthesised."],["b","Medals and ranks. Six medals per planet (clear, no ships lost, untouched, warp"],["b+","found, chain 50, three perfect shifts) and a rank from D to SS, shown on the"],["b+","solar map."],["b","Daily Run. One seed for everybody each day, with one helpful and one hurtful"],["b+","twist picked from the date. No continues."],["b","Best-run ghost. The simulation is deterministic, so a run is just a seed, a"],["b+","loadout and the inputs. Your best run of each planet flies next to you as a"],["b+","ghost."],["b","Screen effects. Colour split on shifts, extra shock rings on big kills, an"],["b+","optional CRT filter."],["b","Two-player co-op. Two ships, one shared upgrade bar. Player one on keyboard,"],["b+","player two on a controller (or two controllers)."],"",["q","'we can also do rivet-9 assist toggle too' ... 'it will be cool to see what"],["q+","rivet 9 looks like when he shift perspectives before we do'"],"",["b","RIVET-9 assist. RIVET-9 is the ArcadeGridz house AI. Switch him on and he flies"],["b+","as your wingman with a light gun. Runs with him are tagged ASSISTED. The first"],["b+","version had him roll into the next view before you did, drawn in that view."],"",["q","'forget having rivet 9 switch perspectives before us it looks funky and"],["q+","illogical lol. just have him do it when we do.'"],"",["b","He now rolls when you roll."],["b","Weak spots. Every boss core carries a hatched, pulsing gold target when it can"],["b+","be hurt and a dim red cross when it is shielded."],["b","Easier to read shots. The main gun fires thicker bolts, the laser has a wide"],["b+","glow, and enemy bullets are bigger spinning rings with a white core and a tail."],["b","A further horizon. Buildings, walls and other scenery are placed much further"],["b+","out and fade in, so nothing pops up in your face."],"",["h3","10. Third playtest"],["q","'tone down the speed on the obstacles spawning on the first boss again ... if"],["q+","a upgrade is maxed out it should skip it ... i still cant seem to get the warp"],["q+","to work'"],"",["b","First boss, slower again. OVERSEER's walls come about a third less often, charge"],["b+","for longer and leave wider gaps. Its bullets and thrown gates are slower too."],["b","Three ranks per weapon. SPREAD, LASER, WAVE, BOLT and MISSILE now max at 3"],["b+","instead of 5. The weak early ranks are skipped, so rank 3 is still the full"],["b+","effect. Drones go up to 6. Boss health went up to match."],["b","The bar skips what is maxed. A pod never lands the highlight on a full slot."],["b","Pods are gold and blue."],["b","God mode is one beam. A single thick hyper beam that fires on its own in"],["b+","explosive pulses."],["b","Warps you can actually take. Each warp now fades in during the calm opening"],["b+","stretch of a level and hangs in front of you for about fifteen seconds before it"],["b+","fades out. In the flat views it is only a flickering sliver. Roll into CHASE"],["b+","view and it opens into a ring you can fly through."],["b","Missiles you can see. Finned rockets with smoke trails, a blast on every hit."],["b","Menus. Holding a button no longer presses a menu item over and over. SAVE AND"],["b+","QUIT now saves the exact spot instead of the last checkpoint."],"",["h3","11. Fourth playtest: every planet its own"],["q","'each boss needs its own unique mechanics ... the levels need more of their"],["q+","own unique level themed mechanics too. not just giant boxes that get in the"],["q+","way'"],"",["b","Bosses stop sharing tricks. The grid walls and thrown gates now belong to"],["b+","OVERSEER alone."],["b","THE COLOSSUS ends with widening rings of fire that have one gap."],["b","THE EYE is new from top to bottom: lightning that walks down the lane behind"],["b+","warning rings, a stare that locks onto your height and fires, a cyclone that"],["b+","drags you in while spiral arms of sparks sweep the deck, and storm orbs that"],["b+","circle the pupil and soak up shots."],["b","THE SHIFTER throws walls of mutant blobs you have to burst, and rows of"],["b+","tentacles that erupt along whole lanes."],["b","The camera pulls back for bosses."],["b","Earth: neon billboards to shoot down, freight lifts riding between the skyways,"],["b+","blinking laser fences, cross traffic between the towers, and a second, faster"],["b+","stream of hover traffic with buses."],["b","Mars: rivers of lava that wander across the floor, lavafalls that pour and stop,"],["b+","basalt boulders to blast, boulders that roll."],["b","Jupiter: drifting fog banks, ammonia ice that grows across the one open lane,"],["b+","wandering tornadoes, floating storm buoys that shoot."],["b","Planet X: blob walls to burst, spore pods that pop into rings of acid, long"],["b+","tentacles that whip right across the forest."],["b","Upgrade bar: MISSILE and SPREAD swapped places, so the screen does not fill with"],["b+","spread shots early."],["b","A shorter title menu. PLAY, OPTIONS, HIGH SCORES, DEVLOG, EXIT GAME. Continue,"],["b+","New Game and Co-op live under PLAY. The solar map is still in the pause menu."],["b+","The Daily Run is shelved."],["b","The map before every hop. Going to the next planet, into a bonus stage or back"],["b+","out of one, the solar map comes up first and the ship flies from where you are"],["b+","to where you are going. Then hyperspace."],["b","Speed. Jupiter and Planet X were dropping frames. Faint lines, sparks and smoke"],["b+","no longer get the expensive glow passes, and the game now steps its own quality"],["b+","down if frames run long."],"",["h3","12. Fifth playtest"],["q","'add a bonus that affects rank based on how fast you beat it because maybe"],["q+","sometimes people are changing their speed'"],"",["b","Time counts. Every planet has a par time. Beat it for a FAST CLEAR medal (a"],["b+","seventh medal, so the top rank is now SSS), and the faster you finish the bigger"],["b+","the time bonus. Flying the whole level at slow speed will not make par."],["b","Progress bar. A bar under the view tabs shows how far through the level you are,"],["b+","with the checkpoints marked."],["b","The ship leans. It banks when it slides sideways and noses up or down when it"],["b+","climbs or dives."],["b","Weapons grow differently."],["b","LASER is one beam that gets thicker and hits harder with each rank, instead of"],["b+","extra rows."],["b","MISSILE keeps two up front and adds rockets out of the back: two at rank 2, four"],["b+","at rank 3."],["b","SPREAD covers your tail with two rear shots at max rank."],["b","BOLT fires one bolt at a time, faster with each rank."],"",["h3","13. Sixth playtest"],["q","'those box looking obstacles dont really make any sense in any level except"],["q+","the first one. you need to improvise different shapes and landscapes for the"],["q+","other levels'"],"",["b","No more crates off Earth. The same obstacles are now drawn as ragged rock"],["b+","outcrops on Mars, scalloped cloud banks on Jupiter and quivering slabs of tissue"],["b+","on Planet X. Earth keeps its buildings."],["b","More to shoot. Every planet has roughly half again as many enemy waves, with"],["b+","divers between the flights."],["b","A wider view. The whole game is zoomed out a notch, and bosses pull the camera"],["b+","back further still."],["b","The Eye's beam makes sense now. It turns to follow you, holds still for a"],["b+","moment, then fires one big beam straight out of its pupil."],["b","Lightning chains read in every view. Seen end-on in the flat views they used to"],["b+","be a dot. Now they crackle."],["b","Solid bosses. Each boss has a shaded body behind its wireframe."],["b","The shield hugs the hull. One outline around the ship per layer, up to three."],["b","Mars, again. The lavafalls are thick, rippling curtains now, there are more"],["b+","rivers of lava, and THE COLOSSUS was re-cut so it reads as a giant stone head"],["b+","from every side: flat top with a topknot stone, a heavy brow shelf, a long nose,"],["b+","pursed lips, a jutting chin, long ears and buried shoulders."],["b","Pods always pay. Buying anything is worth 500 points, so pods still matter when"],["b+","everything is maxed."],["b","A lost ship takes its weapons with it. Drones stay, the guns start over. It was"],["b+","too easy to max everything by the middle of the second planet and never look"],["b+","back."],"",["h3","14. Seventh playtest: busier, wider, easier to read"],["q","'the levels should be really busy but with enough time to react to everything'"],"",["b","Wider and taller. The lane is a little wider and higher, and the camera sits"],["b+","further back again, in levels and in boss fights."],["b","Far backgrounds. Every planet has a distant layer now: a lit skyline with"],["b+","searchlights on Earth, volcano ranges with smoke plumes on Mars, drifting cloud"],["b+","belts and a great storm on Jupiter, swaying stalks with eyes on Planet X. Plus a"],["b+","moon or neighbouring world in every sky."],["b","Earth looks like a city. Buildings have lit windows and blinking masts. The"],["b+","skyways are truss bridges with running lights."],["b","More of everything. More enemy flights on every planet, small things to blast in"],["b+","the gaps, and ground troops: tracked guns on Earth and Jupiter, legged crawlers"],["b+","on Mars and Planet X, on the floor and sometimes the ceiling."],["b","Missiles hug the walls. They are no longer homing: one goes up and one goes"],["b+","down, then they run along the ceiling and the floor. In top view they run along"],["b+","the side walls. That makes them the answer to ground troops. The bolt is still"],["b+","the homing weapon."],["b","More time to shift. The call to change view comes earlier, nothing solid sits"],["b+","around a change of view, and if the view you need is two rolls away a single"],["b+","press takes you straight there. The L or R that gets you there lights up."],["b","Boss walls fade in. They start as a ghost and firm up gradually, and only blink"],["b+","in the last moment."],["b","Catching up. Losing a ship drops a few pods (more in a boss fight), and bosses"],["b+","throw a pod now and then."],"",["h3","15. Arenas and minibosses"],["q","'the in between level bonus arena can be zoomed out quite a bit more and the"],["q+","arena made larger and instead of autoaiming it should shoot the direction you"],["q+","are facing as you move around'"],"",["b","A bigger arena, seen from further back. The floor is about twice the area and"],["b+","the camera pulls well back. The waves are bigger to match."],["b","You aim by flying. The guns fire the way the ship faces, and it faces the way it"],["b+","moves. A right stick or the mouse still aims on its own if you have one."],["b","A miniboss ends every arena. GRID WARDEN patrols a square circuit sweeping four"],["b+","rotating streams. STONE ELDER marks where you stand, leaps there and lands in a"],["b+","ring of fire. THUNDER BLOOM drifts after you trailing spiral arms and calls"],["b+","lightning down. BROOD MOTHER hatches spores and spits fans of acid, faster as"],["b+","she weakens."],["b","A miniboss ends every warp stage too. LUNAR SENTINEL, SOLAR FLARE, THE MOTHER"],["b+","ROCK and FROST WARDEN. The stage only clears once it is gone."],["b","Minibosses scale with you. They are as tough as your guns are strong."],["b","Clearing every wave pays more: 15,000, on top of 5,000 for the miniboss. Dying"],["b+","in an arena still only ends the arena."],["b","Hover traffic you can read. On Earth the cars are colour-coded by height (green"],["b+","low, yellow middle, pink high), each one drops a line to a shadow on the ground,"],["b+","and the altitude meter shows the traffic ahead at its height. There are also"],["b+","about twice as many rows of it."],"",["h3","16. An ending, a credit roll, a loop, achievements and"],["h3+","target order (r22)"],["p","BDC beat THE SHIFTER and nothing much happened. This revision gives the game an end,"],["p+","and a reason to keep going."],"",["b","A real ending. Planet X folds shut, the worlds you saved come back one at a time"],["b+","and the ship flies home. Then something stirs past Pluto."],["b","Planet X now has its arena too. THE HEART and the BROOD MOTHER come after THE"],["b+","SHIFTER, and the ending follows them."],["b","Movie credits. They roll slowly up the screen while the ship and RIVET-9 swoop"],["b+","through in wide figure-eights. Hold the button to speed them up."],["b","Loop the game. After the credits you can start again at Earth with every upgrade"],["b+","and your whole score. The save remembers which loop you are on."],["b","Achievements. Thirty of them, with their own entry on the title menu. They are"],["b+","kept on your device, and idle mode never unlocks them."],["b","Target order. Shoot one of a wave and the next one gets a target on it. Finish"],["b+","the whole wave in that order for a bonus of 300 a head."],["b","Calmer missiles. Smaller rockets, about half as often, less smoke, and never"],["b+","more than two out of the back. Each one hits harder to make up for it."],"",["h3","17. Loops that bite back (r23)"],["p","BDC's order: loop 2 significantly harder, loop 3 extremely difficult, loop 4"],["p+","borderline impossible."],"",["b","Every loop: enemies are tougher (1.7, 2.6, then 4 times the health), their shots"],["b+","are faster, everything that flies now shoots, and it shoots back when it dies."],["b","Hunters. Red divers come at you all level long, more often each loop."],["b","The scroll speeds up: 15, 30, then 50 percent faster."],["b","Bosses shoot at you too, in wider fans each loop, on top of their own attacks."],["b","Shields fade. On loop 3 one hit strips every layer. On loop 4 shields do"],["b+","nothing."],["b","Past loop 4 the enemy just keeps getting tougher."],"",["h3","18. The wave is a wave (r24)"],["b","One wave, not several. The wave weapon is now a single stream that snakes out of"],["b+","the ship along a sine curve, drawn as a glowing ribbon with a white-hot core and"],["b+","a trail of sparks."],["b","Upgrades wind it up. Each rank tightens the frequency, swings it wider and hits"],["b+","harder, and the colour climbs from cyan to violet to hot pink. No extra waves"],["b+","above or below the ship."],["b","It still passes through walls, and it ripples slowly so the curve never sits"],["b+","still."],"",["h3","19. Clean results screens (r25)"],["b","GAME OVER and the clear screens now hide the HUD, so nothing overlaps the"],["b+","results. The level keeps running behind them, a little brighter than before."],"",["h2","Day 2 - Thu 12 Nov 2026"],"",["h3","20. Enemies you can watch die (r26)"],["p","BDC's note: everything was dying in one shot before you even noticed it."],"",["b","Twice the health on every ordinary enemy. Bosses and minibosses are unchanged."],["b","Health bars appear over anything that is being hit and fade a moment later."],["b","Damage numbers float off whatever you are hitting, in small batches so they stay"],["b+","readable. Score numbers still float up on a kill."],["b","A wider view again. The camera sits further back in levels, and further still"],["b+","for bosses and arenas."],"",["h3","21. Tougher still, a slower pace and a fourth speed (r27)"],["b","Enemy health scales with your guns. Doubling it was not enough once the weapons"],["b+","were built up, and a flat four times starved a fresh ship of kills and pods. So"],["b+","ordinary enemies now start at 1.6 times their old health and climb as you"],["b+","upgrade: about four times by mid-game, just over five at full power."],["b","The levels move slower, and there are four speeds now: SLOW, CRUISE, FAST and"],["b+","TURBO. Slow is about a sixth slower than it was turbo is the old top speed. Par"],["b+","times are longer to match."],["b","Changing speed is called out. SHIFTING UP or SHIFTING DOWN shows over the ship"],["b+","with the new speed, and the announcer says it."],"",["h3","22. Traffic from behind, and a building site (r28)"],["b","Hover traffic is a CHASE section now. BDC found it far more fun from behind the"],["b+","ship than from the isometric view, so the level calls for CHASE there."],["b","A construction zone takes the ISO slot on Earth. Half-built girders at every"],["b+","height, crane loads swinging across the lane on their cables, crate stacks to"],["b+","shoot through for gems and pods, and turrets on the ground. It sits between the"],["b+","firewall gates and the traffic, so the level is a little longer and its par time"],["b+","went up to match."],"","",["h3","23. Room to fly, a kinder hitbox, and things that look like"],["h3+","what they are (r29)"],["b","The ship can fly much further forward. The forward limit moved out by two"],["b+","thirds, and bosses hold further back near the edge, so there is more room to"],["b+","read their attacks."],["b","A smaller hitbox. Only the hull counts now. Wing tips and the tail pass through"],["b+","things, so a car you have already cleared no longer clips you from behind."],["b","Hits flash red. Enemies and bosses blink red for a split second when a shot"],["b+","lands."],["b","Earth's obstacles are drawn as what they are. Hover cars are wedges with a glass"],["b+","canopy, headlights, tail lights and hover pads buses are long slabs with a row"],["b+","of windows. Girders are yellow I-beams with rivets and hazard stripes, slung on"],["b+","cables or stood on posts. Cranes are lattice masts with a cab, a jib out over"],["b+","the lane and a counterweight their loads hang on four slings and a hook. Crates"],["b+","have straps, and the wider towers get a rooftop pad."],["b","The Sun stage has solar satellites. The shade lanes are now the panels of"],["b+","satellites, each with a gold body, a dish and antennas."],["b","Solar flares. Big bright prominences loop up off the surface and whip across the"],["b+","lane, five in the first half and four in the second."],["b","A fix on the Sun. The heat kept climbing during the miniboss, after the last"],["b+","shade had gone, so the stage could end there through no fault of yours. The heat"],["b+","now stops once the miniboss arrives."],"",["h3","24. Nothing off Earth is a box (r30)"],["p","The second half of BDC's note from r29: smoother, more organic shapes on the other"],["p+","worlds."],"",["b","Mars, Jupiter and Planet X. Every plain obstacle is now drawn as a rounded body"],["b+","with a flat foot where it meets the ground or the roof: chamfered boulders with"],["b+","facet lines on Mars, scalloped cloud banks on Jupiter, bulging tissue that"],["b+","breathes on Planet X. Seen from above they are rounded outlines with an inner"],["b+","contour, not rectangles."],["b","Asteroids and boulders use a new lumpy twelve-point rock in place of the old"],["b+","diamond, and Mars boulders lost the square behind them."],["b","Ice is cut stone. Small ice blocks are irregular gems with facets, the Pluto"],["b+","shelf is a jagged sheet with cracks, and Pluto's spires are six-sided crystal"],["b+","shafts drawn to a point."],["b","Bigger solar flares. Wider strands, thicker glow, a slower sweep and a bigger"],["b+","hitbox to match in the first half of the Sun stage."],"",["h3","25. Centred views, lava that crosses your path, and arenas"],["h3+","with a floor worth looking at (r31)"],["b","The view is centred again. Pulling the camera back had left dead space at the"],["b+","bottom of the top-down view and down the left of the side view, most obviously"],["b+","in the arenas. Each view now zooms out from its own anchor, so the field sits"],["b+","between the HUD and the upgrade bar. The side view also pulls back a little less"],["b+","than the others."],["b","Mars lava rivers flow across the lane. They are wide, they stream sideways, and"],["b+","they no longer block. Instead the lava drags the ship to a crawl and fills a"],["b+","heat meter: cross one at the slowest speed and you overheat and take a hit."],["b+","Shift up, or dash forward, and you get through with heat to spare."],["b","Arena floors belong to their planet. Earth is a circuit board with pulses"],["b+","running down the traces. Mars is a cracked crucible with glowing fissures, lava"],["b+","at both ends and braziers in the corners. Jupiter is a slowly turning storm"],["b+","spiral ringed with cloud. Planet X is a beating heart with veins running out to"],["b+","eye stalks."],"",["h3","26. The real logos (r32)"],["b","The opening GRiDDiM and ArcadeGridz screens now show the actual logos when their"],["b+","image files sit beside the game (src/logo-griddim.png and"],["b+","src/logo-arcadegridz.png). On ArcadeGridz they do. Where the files are missing"],["b+","the game falls back to the drawn versions, so nothing breaks."],"",["h3","27. A sleeker font, shots that stop, a leaner gun, and"],["h3+","worlds with less grid (r34)"],["b","The font. Every corner of every letter is now rounded and the whole face leans"],["b+","slightly, so it reads as bent neon tube instead of calculator segments. The zero"],["b+","lost its slash."],["b","Hits keep flashing. Enemies and bosses strobe red while they are under"],["b+","continuous fire, where before they just stayed red."],["b","Shots stop at what they hit. Bullets, the laser, bolts and missiles are all"],["b+","spent on the first enemy or obstacle in their way. Only the wave and the"],["b+","god-mode pulse still pass through. The laser and the main gun hit harder to make"],["b+","up for it."],["b","The main gun fires one bullet. SPREAD now upgrades it: three ahead, then three"],["b+","ahead and one behind, then three ahead and three behind."],["b","Mars has ground, not a grid. Cracked, uneven terrain with rocks and craters, in"],["b+","the level and in its arena."],["b","A cave on Mars. A new ISO section between the fire arcs and the magma tubes:"],["b+","rock spikes rising from the floor and hanging from the roof, pillars, and rocks"],["b+","that let go of the ceiling as you get near and smash on the floor. A red ring on"],["b+","the ground marks where each will land."],["b","More city on Earth. Infill blocks and antenna masts in the opening stretch,"],["b+","extra towers and signs between the rows in the top-down section, and more on the"],["b+","skyways."],["b","Jupiter's cloud is a net. Three layers of fine wavy mesh drift past underneath"],["b+","at different speeds, with one more overhead, and the cloud banks themselves have"],["b+","a soft net of threads across them."],"","","",["h3","28. The boss health bar is back (r35)"],["b","When the bosses were moved further back in r29, the boss health bar and the"],["b+","weak-spot marker were still waiting for the boss at its old distance, so neither"],["b+","ever appeared. Both now show again and the bar drains as the boss takes damage."],"",["h3","29. Arena warps, a map that keeps score, and calmer lava"],["h3+","(r36)"],["b","Arenas are found, not handed out. A planet's bonus arena no longer follows its"],["b+","boss. Each level now hides a second warp, a gold one with no announcement, a"],["b+","little after the first checkpoint. Fly into it from CHASE view and you fight the"],["b+","arena win or lose, you are dropped back at the next checkpoint of the level you"],["b+","left."],["b","Space stations on the solar map. Each arena is a small station tethered under"],["b+","its planet, shown as a question mark until you find its warp. The ship flies to"],["b+","it and back on the map, the same as for the other bonus stages."],["b","Ticks and grades. Cleared planets get a green tick and their rank on the map"],["b+","cleared bonus stages and arenas get a tick."],["b","The lava tide rolls. The rising lava and falling ash in THE COLOSSUS fight now"],["b+","have a proper wave running along the surface and through the layers beneath it."],["b","No more lava lines. The flickering lines over the nearby volcanoes are gone."],["b+","Far-off volcanoes now spit blobs of lava that arc up and fall back."],"",["h3","30. The ground is not flat (r37)"],["b","Hills, slopes and ramps. Every planet now has stretches where the ground rises,"],["b+","levels off and falls away: overpasses and embankments on Earth, dunes and ridges"],["b+","on Mars (one runs through the cave), swells in Jupiter's cloud deck, mounds of"],["b+","tissue on Planet X."],["b","The ship rides over them. A hill does not kill. It lifts the lowest height you"],["b+","can fly at, so there is less room under whatever is overhead. Ground troops"],["b+","stand on the slope."],["b","The floor follows the slope in every view. Side on, a hill is a bright ridge"],["b+","line with hatching beneath it."],"",["h3","31. Boss rush (r38)"],["b","A new mode in the PLAY menu. Twelve fights back to back: each planet's boss,"],["b+","then its arena miniboss, then its warp-stage miniboss, from OVERSEER to FROST"],["b+","WARDEN. No results screens, no map and no story in between."],["b","How it starts each fight. Planets begin at the checkpoint just before the boss,"],["b+","bonus stages just before their miniboss, and arenas skip their waves. You start"],["b+","with a modest loadout and five ships, and carry upgrades, ships and score from"],["b+","fight to fight. Here a hit in a bonus stage costs a ship like anywhere else, not"],["b+","the whole stage."],["b","Score and time. A clock runs while you play and shows in the HUD with the fight"],["b+","number. The end screen gives fights won, time and score, and your best run is"],["b+","kept and shown in the PLAY menu. Beating all twelve unlocks a new achievement,"],["b+","GAUNTLET."],["b","Also fixed: the WEAPONS LOST callout when you lose a ship had been silently"],["b+","switched off by a stray comment."],"",["h3","32. Extra ships (r39)"],"",["b","1UP pickups. Enemies now sometimes drop an extra ship: a small green ship"],["b+","turning inside a purple ring with a plus sign beside it. They are rare, but one"],["b+","is always due after enough kills, so every level should show at least one."],["b+","Picking it up adds a ship (up to nine) with a '1UP!' callout at nine it pays"],["b+","5000 points instead."],["b","Ship counter. The HUD still shows six ship icons, with a '+N' beside them when"],["b+","you hold more."],"","",["h3","33. Bomb upgrades, a bigger playfield and two ship skins"],["h3+","(r40)"],"",["b","Bombs upgrade. The power-up bar has a new BOMB slot with three tiers, so spare"],["b+","pods have somewhere to go. The basic bomb is now a short burst around the ship."],["b+","Tier 1, SWEEP BOMB, is a rectangle that rolls out from the ship over a much"],["b+","bigger area. Tier 2, SCATTER BOMB, sets off eighteen diamond blasts across the"],["b+","screen, half of them on enemies. Tier 3, MEGA NUKE, pulls everything in for half"],["b+","a second and then takes out the whole screen. The tier survives losing a ship,"],["b+","like drones do."],["b","More room. The camera is in effect 30% further back with the levels 30% bigger"],["b+","to match: the ship, enemies, shots and pickups are all drawn and collide about a"],["b+","quarter smaller against the same level layouts. Gaps, lanes and gates are that"],["b+","much roomier and buildings that much taller next to the ship. Drone formations,"],["b+","the wingman and the idle-mode pilot were resized to match."],["b","Taller skyline. Earth's opening run has taller and more varied towers, with"],["b+","blocks hanging from above where the tower below is short."],["b","Hit flash. The red flash on enemies and bosses strobes slower and lasts longer,"],["b+","so it reads as a flash when you are pouring fire in."],["b","Ship skins. OPTIONS has a SHIP SKIN setting. FIRE MAGE turns the ship into a"],["b+","firebat with flapping wings and embers, and every weapon into fire: flame darts,"],["b+","a wavering stream of flame, fireball missiles, ember drones. DARK LORD is a"],["b+","wraith stealth ship trailing a ragged cloak, with shadow bolts, a violet beam,"],["b+","soul-green lightning and wisps for drones. Skins only change the look. FIRE MAGE"],["b+","unlocks by beating the second boss and DARK LORD by beating the last one the"],["b+","options menu previews a locked skin on the title screen."],"","","","","","",["h3","34. Seeing further, hyperdrive and set-and-forget bombs"],["h3+","(r41)"],"",["b","See further ahead. The last pass made room around the ship but showed no more of"],["b+","the level ahead, which was the point of asking. Now the distance ahead is"],["b+","squeezed on screen by the same 30%, so about a third more of the level is in"],["b+","view in every view, and the ship can fly a third further up it. Enemies and"],["b+","scenery are placed that much further out so nothing appears inside the picture."],["b+","Ships, enemies and rings are stretched back so they keep their shape. Boss"],["b+","fights and arenas keep their own camera."],["b","Hyperdrive. The wildcard slot at the end of the bar is gone. In its place is"],["b+","HYPER, which stays locked until drones, every weapon and the bomb are maxed. One"],["b+","pod then switches hyperdrive on for good: 15% more damage from everything, kept"],["b+","when you lose a ship, and the ship glitters while it is on."],["b","Auto detonate. A new option sets off a bomb every ten seconds for as long as you"],["b+","have one."],["b","Back to slow. Losing a ship drops the speed back to SLOW, so the next one is not"],["b+","thrown straight into traffic."],["b","Red targets. The target marker on the next enemy in a wave is red now in yellow"],["b+","it looked too much like a pickup."],["b","Skins in the store. FIRE MAGE and DARK LORD can now also be bought with Sparkz"],["b+","in the site's store, as well as earned by beating the bosses."],"","",["h3","35. A bug test checklist (r42)"],"",["b","BUG TEST. The title menu and the pause menu have a BUG TEST checklist: every"],["b+","planet, warp stage and arena, Boss Rush, and the ending with its loop. Picking"],["b+","one starts you there with no damage: hits are marked on screen and counted, but"],["b+","nothing is lost, so the weapons and upgrades behave as in a real run and you buy"],["b+","them by hand. Planets start with roughly the loadout you would have by then."],["b+","Clearing one ticks it off, and the list is kept between sessions."],["b","Clean test runs. Test runs never post scores and do not unlock achievements,"],["b+","skins, medals, ghosts or Boss Rush records."],["b","One switch for release. When the list is done, a single flag hides the checklist"],["b+","and the solar map's level-jump test buttons together for the jam build."],"",["h3","36. A new voice (r43)"],"",["b","The announcer is a woman now. A calm, close, unhurried voice, picked from the"],["b+","best female voice the browser offers, a little lower and slower than normal"],["b+","speech."],["b","Title voiceover. The title screen says the name: 'two-diso ... shift'."],["b","ISO is a word. The announcer used to spell out I-S-O it now says 'eye-so', like"],["b+","the rest of us."],"",["h3","37. Test tools: any skin, any loadout (r45)"],"",["b","Skin picker in BUG TEST. Wear any skin for testing, locked or not. It only works"],["b+","while the test menu exists, so it goes away with it."],["b","Loadout manager in BUG TEST. Set drones, each weapon, bomb tier, hyperdrive,"],["b+","shields, bombs and ships by hand every test, Boss Rush included, starts with"],["b+","that loadout. MAX EVERYTHING and EMPTY are one press each."],["b","A shorter pause menu. Idle mode and the RIVET-9 assist only live in OPTIONS now."],"",["h3","38. A new logo (r46)"],"",["b","A display face of its own. The title logo is no longer set in the in-game font."],["b+","It has its own geometric letters, built from chamfered strokes with a dark"],["b+","keyline, a hot core and a chrome gradient. 2DISO leans a little in cyan and blue"],["b+","SHIFT leans hard in pink and violet."],["b","SHIFT is sliced. A seam runs through SHIFT and its top half sits shifted"],["b+","sideways, as if the view was caught mid-roll. Every couple of seconds it jolts"],["b+","further."],["b","New tagline. 'Shift the view. Shift the rules.'"],"",["h3","39. Pill buttons, a fifth speed and a fairy (r47)"],"",["b","Menus look like the site. Menu items are neon pill buttons, as on ArcadeGridz"],["b+","and in the app: a cyan outline at rest, the chosen one lit amber and lifted."],["b+","Option rows show their left and right arrows inside the lit pill. The title menu"],["b+","floats over the attract run with no box behind it, and other menus sit on a soft"],["b+","rounded glass card."],["b","A bolder menu font. Menu items and titles use a new bold style of the vector"],["b+","font: thick strokes, corners cut square instead of rounded, a bit more lean and"],["b+","more room per letter."],["b","HYPER. A fifth speed above TURBO, for going very fast."],["b","The god-mode beam reaches the far edge of the bigger field again, and so do the"],["b+","laser and the drones' beams."],["b","The wave hits harder (about half as much again at every rank), and its top rank"],["b+","is gold so it no longer looks like rank 2. The skins got the same fix."],["b","The title voice says it right: 'two-DIE-so', a beat, then 'shift'."],["b","A cooler tagline. Under the logo it is now bold and in two colours, 'SHIFT THE"],["b+","VIEW' in cyan and 'SHIFT THE RULES' leaning in pink, with a lit chevron between"],["b+","them and brackets either side."],["b","PIXIE skin. The ship becomes a fairy: a glowing body, four butterfly wings that"],["b+","flutter, antennae and a falling trail of glitter. Shots become twinkling stars,"],["b+","missiles little spinning stars, drones fireflies, and every beam and wave turns"],["b+","pastel. Beat the Eye on Jupiter to earn it, or buy it in the Sparkz store."],"",["h3","40. Red fog, gas clouds and a hyper run (r48)"],"",["b","The Sun, rebuilt. The solar panels are gone. The Sun's atmosphere is now thick"],["b+","red plasma fog with one clear winding channel through it stay in the channel to"],["b+","stay cool. Solar flares are bigger, with five twisting strands, bright knots and"],["b+","glowing feet."],["b","Jupiter's gas clouds. Big clouds drawn as a fine wavy mesh drift by slower than"],["b+","the level, so enemies and obstacles slip behind them for a moment."],["b","Jupiter recoloured and longer. Greens, purples and fuchsia instead of brown,"],["b+","more enemies everywhere, and a new chase section, THE DEEP, full of sharks and"],["b+","jellyfish to dodge."],["b","Mars eruptions are now columns of fire instead of lines."],["b","Planet X hyper run. A section near the end locks you at HYPER speed. Walls flash"],["b+","where they are about to appear, then turn solid."],["b","Warnings. Some enemy waves flash on screen just before they arrive, and the gold"],["b+","warps now come with an ANOMALY DETECTED call and a hint, plus a slightly bigger"],["b+","catch area."],["b","Bosses call in waves of their level's enemies during the fight, and in chase"],["b+","view they are drawn bigger so you can see their faces."],["b","Solid enemies. Every enemy has a shaded body behind its outline, so nothing is"],["b+","just a pair of crossed lines any more."],["b","More hills and ramps on every planet, and the bonus stages lean on chase and iso"],["b+","views."],["b","Smoother. Quality steps down sooner when frames slow down and comes back once"],["b+","things settle."],"","",["h3","41. Ragged holes and real boulders (r49)"],"",["b","No more square holes off Earth. In chase view a gate on Mars, Jupiter or Planet"],["b+","X is now one wall of rock, cloud or flesh with a ragged rounded opening, a"],["b+","tunnel rim, and cracks, ripples or veins spreading out from it. A soft green rim"],["b+","inside marks the way through. The opening is drawn slightly inside the real gap,"],["b+","so the edge never kills you before it looks like it should. Earth keeps its"],["b+","square building gaps."],["b","The Sun's fog is drawn the same way in chase and iso: slice after slice of red"],["b+","fog with a rounded hole for the channel."],["b","Rocks look like rocks. Rocks on every planet bulge in the middle and taper front"],["b+","and back instead of being extruded blocks, with round shaded lobes instead of"],["b+","box fills. The Moon trench is now a ragged line of boulders of different sizes"],["b+","instead of a row of cubes."],"","","",["h3","42. RIVET-9 on comms (r50)"],"",["b","Tips come from RIVET-9. View calls, hazard tips and anomaly alerts now pop up as"],["b+","a little instant-message window in the top left, with his portrait, a title bar"],["b+","and the text typing out. It stays up long enough to read, fades away on its own,"],["b+","and he reads it out loud. If a second message comes in, the first slides down"],["b+","and fades."],["b","He overreacts, on purpose. His face is an emoji on a visor and changes as he"],["b+","talks: shocked then starry-eyed at an anomaly, panicking with a sweat drop at"],["b+","lava, sharks and lightning, angry eyebrows at a boss, a smug grin when it's time"],["b+","to shift. His mouth flaps while the words come out, he shakes when he's scared,"],["b+","and every message opens with WHOA!!, YIKES!, GET HIM! or OOH!"],["b","The big calls stay big. Stage names, waves and other headline calls stay as"],["b+","centre-screen banners, now in the thick bold font along with the level titles,"],["b+","results screens, boss names, warnings and score pop-ups."],"","",["h2","Day 3 - Fri 13 Nov 2026"],"",["h3","43. Warps you have to mean (r51)"],"",["b","On Earth the arena warp could still be hanging around when the level asked you"],["b+","to shift to chase view, so you could fall into it by accident and skip a good"],["b+","stretch. Every warp now appears in a stretch that isn't played in chase view,"],["b+","and closes before the next chase stretch, so taking one is always a choice."],"",["h3","44. Boss rush warp stages fixed (r52)"],"",["b","In boss rush the four warp stages said complete straight away. Boss rush dropped"],["b+","you in just past the point where the miniboss is called in, so it never came."],["b+","Boss rush now looks up where each stage's miniboss arrives and starts you just"],["b+","before it."],["b","The red HIT markers from bug testing are gone. Bug test still counts your hits"],["b+","on the results screen."],"",["h3","45. Tabs, surprise shifts and tougher blob walls (r53)"],"",["b","Options in tabs. SOUND, VIDEO, PLAY, SHIP and MORE. Flip tabs with L / R, or"],["b+","left / right on the tab row."],["b","Reality shifts in the levels. The fold now flips your view for you once or twice"],["b+","on every planet, not only in the last boss fight. Where it happens is random"],["b+","each run, but always somewhere in the middle half of the level and never right"],["b+","on a change of view. Roll back yourself."],["b","The last boss's blob walls hold. They have more than ten times the health and"],["b+","scale with your guns, so it now takes a few seconds of focused fire to burst one"],["b+","before it reaches you."],"","",["h3","46. Cutscenes between planets (r54)"],"",["b","A short flight between planets. After each boss, before the map and hyperspace,"],["b+","there is a short scene. The world you saved slides away behind you, the next one"],["b+","looms up with the rift cracked across it, and you fly with RIVET-9 tucked in"],["b+","behind. He talks you through it on comms, with his face doing the acting: proud,"],["b+","then panicking, then fired up."],["b","RIVET-9 calls the reality shifts in the levels and in the last boss fight, with"],["b+","a WHOA WHOA WHOA! and a shocked face."],"","",["h3","47. A story between the planets (r55)"],"",["p","The cutscenes now tell a story, five lines each, and it carries through to the"],["p+","ending:"],["b","Earth to Mars. RIVET-9 used to work for OVERSEER (he was its spellchecker)."],["b+","Before it crashed it sent one word to Mars: WAKE. The stone heads there are not"],["b+","statues. They are antennas the Fold listens through."],["b","Mars to Jupiter. THE COLOSSUS talked on the way down: the Fold cannot see depth"],["b+","and only ever sees one side at a time. That is why it hates a pilot who sees all"],["b+","four. So it grew an eye inside Jupiter."],["b","Jupiter to Planet X. RIVET-9 pulls coordinates out of the Eye's last look."],["b+","Planet X is not a planet. It is a dream that something far past Pluto is having,"],["b+","and the only hope is to break the dream so the dreamer stays asleep."],["b","The ending's last line now points back at the dreamer. Each line also stays on"],["b+","screen longer, so the whole thing can be read and heard."],"","",["h3","48. A jam banner on the title screen (r56)"],"",["b","The Game Off note on the title screen is now a neon pennant hanging in the top"],["b+","right corner: GITHUB GAME OFF 2026, THEME: SHIFT and a DEVLOG button. It sways,"],["b+","glints and glows brighter when you point at it. Click or tap it, or press the"],["b+","drone button, to read the devlog. The DEVLOG item has left the title menu."],"",["h3","49. Skin previews (r57)"],"",["b","The SHIP tab in Options now shows the skin you are looking at as a turning"],["b+","model, with dots for all four skins. A skin you have not earned is a dim"],["b+","silhouette with a padlock, plus what unlocks it: beat the boss, or the Sparkz"],["b+","price from the store (FIRE MAGE: THE COLOSSUS or 500, PIXIE: THE EYE or 650,"],["b+","DARK LORD: THE SHIFTER or 800)."],"","","",["h3","50. Skins drop from the warp stages (r58)"],"",["b","A reason to find the warps. Skins no longer come from the main bosses. Each one"],["b+","drops from the miniboss of a hidden warp stage: FIRE MAGE from SOLAR FLARE on"],["b+","the Sun (warp on Mars), PIXIE from THE MOTHER ROCK in the Asteroid Belt (warp on"],["b+","Jupiter), DARK LORD from FROST WARDEN on Pluto (warp on Planet X). You can still"],["b+","buy them with Sparkz."],["b","The music slider works. Each sound bus used to go into one shared compressor"],["b+","that evened the volume back out, so turning the music down barely changed"],["b+","anything. Music and sound effects now each have their own compressor, the"],["b+","sliders come after it, and a limiter at the very end only catches peaks."],["b","SHIP is the first options tab."],"",["h3","51. A cleaner, smoother title screen (r59)"],"",["b","Smooth title. No game plays behind the title any more. The backdrop is now a"],["b+","slow starfield over a rolling neon grid floor, with a pink glow on the horizon,"],["b+","and it costs almost nothing to draw. In a test it went from about 15 to 55"],["b+","frames a second."],["b","New layout. Your ship turns in the middle of the screen in the skin you have"],["b+","equipped, and the menu sits under it in two centred rows."],["b","BUG TEST has moved out of the title and pause menus into Options, on the MORE"],["b+","tab."],["b","The title voice says the whole name again. In some browsers a line spoken"],["b+","straight after another one was cut gets dropped, so the 2DISO part was being"],["b+","lost and only a rushed SHIFT came through. The title is now one slower line with"],["b+","a real pause in the middle."],"","",["h3","52. A devlog you can actually read (r60)"],"",["b","Entries fold up. The in-game devlog used to be one long wall of text. Now every"],["b+","entry is a single line until you open it, and only one is open at a time. Tabs"],["b+","along the top split it into the backstory, each day of the jam and the to-do"],["b+","list, and the screenshots from this page appear inside the entries they belong"],["b+","to."],["b","The DEVLOG button is back on the title menu, on the second row between"],["b+","ACHIEVEMENTS and EXIT. The jam banner in the corner is now just a banner."],"","","","",["h3","53. Ice, land and better crawlers (r61)"],"",["b","Pluto rebuilt. It was the dullest stage. Now the ice shelf has icicles hanging"],["b+","over it, the chase stretch throws snowflake comets at you (six-armed flakes with"],["b+","long icy tails) between cryo geysers that blast columns of ice crystals, icicles"],["b+","hang from above and spikes grow from below, and the last stretch is a field of"],["b+","drifting icebergs in iso view. Snow falls the whole way."],["b","No more boxes round spikes. Rock spikes and icicles used to sit inside a shaded"],["b+","box that ran right up the point. They are now filled face by face as cones."],["b","Eruptions without the glitch. Lava geysers, in the level and in THE COLOSSUS"],["b+","fight, used to flash a box while they built up and stand in a box once they"],["b+","blew. Now a ghostly column of rising rings marks where one is about to go, and"],["b+","the eruption is just fire."],["b","Crawlers. The ground walkers were a ball on four sticks. Now they are six-legged"],["b+","armoured mech crabs with a domed shell, a red eye that tracks you and twin guns,"],["b+","stepping in two sets of three. They are a bit bigger and turn up more often, in"],["b+","pairs."],["b","Earth stands on land. The city floor used to be a grid over open space with"],["b+","stars showing through. Now it is solid ground: an asphalt road with kerbs, lane"],["b+","lines and zebra crossings, and street lamps along both pavements."],"","","","","",["h3","54. Blob walls you can read (r62)"],"",["b","THE SHIFTER's blob walls cycle through the rainbow, flash solid red every time"],["b+","you hit them, and carry a health bar that goes from green to yellow to red. The"],["b+","red and the bar keep their true colours even on the trippy planet, where"],["b+","everything else shifts hue."],"","",["h3","55. Tougher minibosses, a fuller bug test (r63)"],"",["b","Warp-stage minibosses last. LUNAR SENTINEL, SOLAR FLARE, THE MOTHER ROCK and"],["b+","FROST WARDEN went down in about three seconds, too fast to see what they do."],["b+","They now have four times the health: around 12 seconds with maxed guns and 15 to"],["b+","20 with weak ones. The arena champions get half again as much."],["b","Bug test: every boss on its own. The list now has all four bosses and all four"],["b+","warp-stage minibosses as separate entries. Each one drops you in just before the"],["b+","fight and ticks off when you win it."],["b","Bug test: no warps. Bug test runs of the planets no longer spawn warps, so you"],["b+","can't fly into one by accident and leave the level you are testing."],"",["h3","56. Room to fight (r64)"],"",["b","Warp-stage minibosses used to park close in front of you, leaving little room to"],["b+","back off. They now come in from further away and hold well up the lane, so there"],["b+","is space to dodge and fight."],["b","The pop-up cards in the corner grow to fit their text. A long one, like the tick"],["b+","for the MOTHER ROCK test, used to spill out of its card."],["b","On the Sun the heat meter drops below a boss or miniboss health bar instead of"],["b+","sitting on top of it."],"",["h3","57. Smooth first: graphics settings and dynamic framerate"],["h3+","(r65)"],"",["p","A proper look at where the time goes. The answer was clear: the game logic costs"],["p+","almost nothing (about a quarter of a millisecond a frame). Nearly all of a frame is"],["p+","spent painting glowing lines, and the cost grows with how many pixels there are and"],["p+","how many times each line is painted."],"",["b","GRAPHICS: HIGH / NORMAL / LOW in Options, VIDEO tab. HIGH is the full look."],["b+","NORMAL keeps the glow but softer, at three quarters of the resolution. LOW has"],["b+","no glow, half the resolution and no far skyline it is plain but sharp and"],["b+","readable."],["b","DYNAMIC FRAMERATE (on by default). It watches the frame time while you play. If"],["b+","frames run long it drops a step within a second, faster if things are really"],["b+","bad, and climbs back after ten smooth seconds. If it climbs and has to drop"],["b+","again straight away, it waits twice as long before the next try, so it does not"],["b+","bounce. There is one emergency step below LOW that only this can reach. The"],["b+","option shows the step it is on."],["b","Cheaper glow at every setting. The halo round each line used to be painted twice"],["b+","at full size. Now the glow is painted once into a small off-screen buffer and"],["b+","laid over the picture, and the wide outer halo is that same buffer shrunk and"],["b+","stretched. It looks the same and takes one pass fewer per colour."],["b","Cheaper text on the lower settings: the neon halo on HUD text goes first."],"",["p","On a test machine with no graphics card at 1080p, the same Mars stretch went from 29"],["p+","frames a second on HIGH to 44 to 48 with dynamic framerate on."],"",["h3","58. Everything goes through RIVET-9 (r66)"],"",["b","No more centre-screen banners. Sector names, waves, minibosses, boss kills, LAVA"],["b+","RISING and the rest now all arrive in RIVET-9's comms window, each with its own"],["b+","opener and face (HERE WE GO!, INCOMING!, UH OH!, YES!!)."],["b","Flashing status warnings moved there too: overheating, flying over lava, a"],["b+","shielded boss core, leaving the clear channel on the Sun and the arena's view"],["b+","call. He says each one once when it starts instead of it flashing in the middle"],["b+","of the screen. The gauges keep a short plain label."],["b","The heat meter no longer sits on top of the level progress bar."],"",["h3","59. Clarity mode (r67)"],"",["b","A new CLARITY switch under VIDEO for when the screen gets busy. The backdrop"],["b+","dims, your own shots, beams and explosions turn translucent, particles and score"],["b+","pops are capped, and enemy bullets always draw on top with a dark backing so"],["b+","they stay readable through everything."],["b","Left: normal. Right: clarity on. Top is the Mars boss in TOP view, bottom is"],["b+","Planet X in SIDE view."],"","",["h3","60. Six ranks for everything (r67)"],"",["b","Every weapon, the shield, the bomb and the hyperdrive now have six ranks, the"],["b+","same as drones. The old top ranks are still the top the new ones in between each"],["b+","add a twist instead of just more damage."],["b","MISSILE: Sparkler, Swarm, Shrapnel (hits throw shards), Barrage, Tagger (marked"],["b+","enemies take more damage), Cluster."],["b","LASER: Penlight, Focus, Mirror (the beam eats bullets), Lance, Capacitor (every"],["b+","fifth pulse hits hard), Prism."],["b","WAVE: Ripple, Wide, Echo (a mirrored second wave), Tidal, Undertow (shoves"],["b+","enemies back), Tsunami."],["b","BOLT: Static, Fork, Magnet Coil (pulls pods in), Chain, Blackout (clears nearby"],["b+","bullets), Storm."],["b","SPREAD: Double Tap, Twin Fan, Piercer, Star Fan, Railgun, Nova Fan."],["b","SHIELD: Film, Barrier, Blowback (losing a layer knocks bullets away), Double"],["b+","Barrier, Afterglow (longer safe time after a hit), Triple Barrier."],["b","BOMB: Wide Ring, Sweep Bomb, Backdraft (a second sweep), Scatter Bomb, Vacuum"],["b+","(pulls in every pod), Mega Nuke."],["b","HYPERDRIVE still unlocks only once everything else is maxed: Overclock, Magnet,"],["b+","Quicksilver (faster fire), Second Wind (one free save per level), Bomb Forge"],["b+","(bombs refill slowly), Singularity."],"",["h3","61. Small fixes (r67)"],"",["b","God mode and overdrive countdowns now live in RIVET-9's comms window instead of"],["b+","the middle of the screen."],["b","Once everything is maxed, pickups stop being upgrade pods. You get the odd bomb,"],["b+","or points."],"",["h3","62. The Labyrinth, and tighter pacing (r68)"],"",["b","Mars has a new stretch between the caves and the magma tubes: THE LABYRINTH, a"],["b+","maze of lava rock seen from above. The forge locks your speed at SLOW the whole"],["b+","way through. One gap in each row is the way on. The other gaps lead into side"],["b+","pockets with gems and pods, sealed at the far end by rock you have to blast"],["b+","through."],["b","Earth was the longest level by a wide margin, so parts of the skyscrapers,"],["b+","skyways and firewall gates are gone. The construction zone and the hover traffic"],["b+","stay in full."],["b","Warp stages are shorter: the run up to each miniboss is trimmed, and the"],["b+","minibosses keep their full health. Bonus arenas have smaller waves, so each one"],["b+","takes about a minute."],["b","The blob walls in the final boss fight have a bit less health."],"","",["h3","63. The Motherlode (r69)"],"",["b","Halfway through the asteroid belt you now fly into one giant hollowed-out rock"],["b+","with a mining colony inside it, played in SIDE view. The cave roof and floor"],["b+","close in, drill rigs pump up and down, ore carts run along the rails, laser"],["b+","fences guard the seams and the ore crates are full of gems. Mining drones patrol"],["b+","it. After that you're back out among the rocks."],"","",["h3","64. The stage moves (r70)"],"",["b","Planet X already rocked the screen a little. Now the whole stage turns, tips,"],["b+","rolls and drifts in many more places, and the controls stay screen-relative: up"],["b+","on the stick is always up on the screen, however the stage is turned."],["b","Jupiter has a new stretch, THE DESCENT. The deck gives way and the stage turns"],["b+","on its side, so you fall straight down through Jupiter's coloured gas bands,"],["b+","threading gaps in the cloud shelves and lightning, until the storm opens into"],["b+","the sea below. A little of the lightning chains and storm walls came out to make"],["b+","room, so the level is about the same length."],["b","Mars: the magma tubes roll all the way round as you fly through them."],["b","Planet X: the fold flips the membranes section upside down, the tentacle forest"],["b+","heaves, and the gullet twists as it carries you along."],["b","Earth: the street banks and weaves through the hover traffic."],["b","Warp stages: the Moon trench floats about in the low gravity, the Sun's channel"],["b+","tips nose-down for the dive, and the Pluto blizzard rocks the stage."],["b","Bosses always fight on a level stage."],["b","Fixed a bug in the level trimming from r68/r69: scenery after a trimmed stretch"],["b+","stayed where it was instead of moving up with the rest."],"","","",["h3","65. Smooth from the first second (r71)"],"",["b","New players now start on NORMAL graphics with dynamic framerate on, on every"],["b+","device. HIGH is still one tap away in VIDEO."],["b","New RESET TO DEFAULTS under OPTIONS > MORE. Press it twice to confirm. Your"],["b+","chosen ship skin stays."],["b","Before the playtest: a full sweep through every level, warp stage, arena and"],["b+","boss at every graphics setting, with clarity on and off, plus every menu."],["b+","Nothing broke."],"",["h3","66. The picture breaks up (r72)"],"",["b","A glitch effect, like an old TV giving out: torn lines, the picture slipping,"],["b+","red and blue splitting apart, static and a rolling band."],["b","It hits just before a reality shift throws you into another view, briefly when a"],["b+","shield layer pops, and hard when you lose a ship."],["b","On your last ship with no shield left, the screen starts to glitch on its own,"],["b+","and more often the longer you stay like that. Pick up a shield and it calms"],["b+","down."],["b","The Shifter attacks the screen itself: between its shells, now and then"],["b+","mid-fight, and in one big burst of static as it dies."],["b","Invisible wraiths on Jupiter fuzz the signal when they get close."],["b","Turning SCREEN SHAKE off tones the glitch right down."],["b","The shield layers around the ship are spaced further apart and only the inner"],["b+","one glows, so you can count them."],"","",["h3","67. Shh-shh-SHIFT (r73)"],"",["b","On the title screen the announcer now says '2diso', then a stuttering SHIFT that"],["b+","echoes away, softer and quicker each time, with a faint electronic ping under"],["b+","each echo."],["b","The ship swooping in at the end of the intro has a sound now: air building to a"],["b+","roar as it comes at you, then a falling doppler as it peels away."],["b","Fixed the old drawn GRiDDiM splash flashing up for a moment before the real"],["b+","logo: the intro now shows nothing until the logo image has loaded, and it waits"],["b+","by the clock instead of counting frames, which ran out early on fast monitors."],"",["h3","68. Splash sounds and two voices (r74)"],"",["b","The GRiDDiM splash hums and crackles like a neon sign powering up."],["b","The ArcadeGridz splash plays a couple of bars of chiptune, finishing on a bright"],["b+","chord."],["b","The ship's swoop sound starts a little earlier."],["b","The title line is now two voices: a female voice says '2diso', then a male voice"],["b+","stutters 'shif, shif, SHIFT!' and echoes away. The voices are picked once the"],["b+","browser has its full voice list, so the first line no longer falls back to the"],["b+","default voice."],"",["h3","69. Tidying the title (r75)"],"",["b","The text on the jam ribbon is sized to fit inside its dashed border."],["b","The stutter is now 'Sh, Sh, SHIFT!', and it and its echoes are spoken faster."],["b","Any real click, tap or key press anywhere on the page now switches the sound on."],["b+","Browsers keep a page silent until you interact with it, and some clicks were not"],["b+","getting through to wake the music."],"",["h3","70. Quieter launch (r76)"],"",["b","The title line is now just a female '2diso', then a male 'SHIFT!' echoing away."],["b+","The stutter is gone: the browser voice kept spelling it out letter by letter."],["b","The game's own sound now waits about a second after launch before starting, so"],["b+","the ArcadeGridz app's coin-drop sound isn't cut off."],"",["h2","Still to do"],["b","Hardware testing: a controller in the ag app, phones, tablets."],["b","Balance by hand. The autopilot clears everything people are not autopilots."],["b","Finish the bug test list, then hide the bug test menu for the jam build."],["b","Recorded announcer lines instead of the browser voice."],["b","Push the HTML5 build to itch.io (the page is set up as a draft) and submit it to"],["b+","the jam."],["b","Retake the itch.io screenshots once the game is final."],""];
export const DEVLOG_TABS = [{"name":"STORY","entries":[{"title":"ABOUT THIS DEVLOG","lines":[["p","A GitHub Game Off 2026 entry (theme: SHIFT). Designed and directed by Benjamin Campbell (BDC"],["p+","/ GRiDDiM), built with Claude as the programmer. Every line of art and every sound is"],["p+","generated by code in this repo."]]},{"title":"HOW WE MAKE GAMES","lines":[["p","2DISO SHIFT was not built from a standing start. It sits on top of a way of working that BDC"],["p+","has been putting together all year."]]},{"title":"THE GRIDDIM BOOTSTRAP","lines":[["p","Griddim is a small network of sites that all share one shell. The rule for the shell is"],["p+","written down as a standard called the bootstrap, and it fits in one line:"],"",["p","Modules own screens. Agents operate on screens."],"",["p","Every site on the network has the same seven parts: a global header, a site header, a left"],["p+","bar of modules, a workspace that shows the active module, a right bar of agents, a site"],["p+","ticker and a global footer. A new site starts from one sentence ('integrate this domain into"],["p+","the network, concept: ...') and the bootstrap fills in the rest, so nobody has to explain"],["p+","the architecture twice, to a person or to a model."]]},{"title":"ARCADEGRIDZ: THE SITE AND THE APP","lines":[["p","ArcadeGridz is the arcade built on that shell. A game there is a module that mounts into the"],["p+","workspace through a small contract:"],"",["b","one mount function that hands back pause, resume and destroy handles"],["b","a shared controller layer, so a game listens for a handful of keys and every pad just"],["b+","works"],["b","a system menu on Start + Select, the same in every game"],["b","an agent panel on the right that shows live stats and Pause / Idle buttons"],["b","shared leaderboards, with runs tagged verified, assisted or cheater"],"",["p","There is also a native Windows launcher, the ag app. It syncs its catalog from the site, so"],["p+","adding a game to the site adds it to the app with no app update."],"",["p","A game counts as ready when it plays on keyboard, controller, phone and tablet, has its own"],["p+","menus with a real exit, pauses itself when it loses focus, and has an idle mode. Ready games"],["p+","are tagged BETA. Most of the catalog began as BDC's old GameMaker projects, rebuilt with the"],["p+","original source as reference rather than as a blueprint."],"",["p","The house rules for game code came out of that work, and this game follows them: the"],["p+","simulation is pure and seeded with a fixed 60 Hz step, players are an array even when there"],["p+","is one, and all input passes through one object per player. That is why the same code can"],["p+","run the title demo, idle mode, a headless test and, later, multiplayer."],"",["p","2DISO SHIFT is a standalone game first. The jam build runs from a single HTML page. A thin"],["p+","adapter file is all that connects it to ArcadeGridz."]]},{"title":"DIFFERENT AI MODELS FOR DIFFERENT JOBS","lines":[["p","BDC directs and the models build. Different models have ended up with different jobs:"],"",["b","ChatGPT and Codex built the original network shell, the first version of the arcade site"],["b+","and the on-site agents, and started the Windows launcher."],["b","Claude builds and maintains the games, and took over the launcher. This game was scoped"],["b+","in a first pass with one Claude model and built with a newer one."],["b","Small local models run the on-site agents day to day, with the larger models as a"],["b+","fallback."],["b","An autopilot inside the game is the tester. It plays every level headless after each"],["b+","change."],"",["p","What makes this work is written handoff. Every session ends with notes on what changed, what"],["p+","version is live and how to roll it back, so the next model, or the next session, starts from"],["p+","facts instead of guesses."],"",["p","BDC's side is the part a model cannot do: deciding what the game is, playing it, and saying"],["p+","what feels wrong. Most of the prompts quoted below are one or two lines long."]]}]},{"name":"DAY 1","entries":[{"title":"1. THE IDEA","lines":[["q","'what do you think about this game jam? can we make a revision of 2diso called 2diso"],["q+","-shift- for this?'"],"",["p","The original 2DISO flipped between a 2D and an isometric view on a timer. The jam theme was"],["p+","SHIFT, so the fit was obvious. Two decisions came out of the first exchange:"],"",["q","'i would want a brand new game ... not just 2diso reskinned or renamed. and yes"],["q+","shifting between views with an action instead of timer was what i was thinking too.'"],"",["b","Checked the jam rules: source must be public on GitHub, existing code and AI help are"],["b+","allowed, but the game should be made for the jam."],["b","Created the public repo and pushed a README and MIT license."]]},{"title":"2. THE DESIGN PROMPT","lines":[["q","'i also want it to shift between an over the shoulder view ... and a birds eye"],["q+","vertical rail view ... so thats 4 different views to shift between.'"],"",["p","This one message set most of the game: four views, a Griddim / ArcadeGridz splash and a ship"],["p+","swoop into the title, neon wireframe arcade art ('that way you dont have to generate"],["p+","sprites'), forced reasons to change view, hidden warps to bonus levels, the planet order"],["p+","(Earth, Mars, Jupiter, Planet X), an upgrade bar where each pickup moves a highlight and you"],["p+","choose when to spend it, drones that survive death, and a random god mode drop."],"",["p","Follow-ups locked the controls:"],["q","'shift should be controlled by L and R buttons. you kind of barrel roll into the"],["q+","views.'"],["q","'A can shoot. Y is bombs. X modifies drone behavior.'"],["q","'use select then to pick the upgrades and put a map menu item in the pause menu"],["q+","instead'"]]},{"title":"3. THE CORE RULE","lines":[["p","The design problem was making four views matter. The answer became the whole game:"],"",["p","What a view flattens does not exist for collisions."],"",["b","SIDE ignores left/right: a full-height skyscraper is a wall, a deck is something to"],["b+","duck."],["b","TOP ignores altitude: a deck is a wall, a skyscraper is something to steer round."],["b","ISO and CHASE keep all three axes: a wall with one hole needs them."],"",["p","One collision function with a per-view axis mask gave every obstacle a different meaning in"],["p+","every view, with no special cases."]]},{"title":"4. BUILD ORDER, FIRST PASS","lines":[["b","1. font.js: a stroke font drawn as line segments, so there are no font files."],["b","2. game.js: pure seeded simulation at a fixed 60 Hz, players as an array, no DOM."],["b","3. An autopilot that plans against predicted obstacle positions. It runs Idle Mode and"],["b+","the title demo, and it plays every level headless as the test suite."],["b","4. render.js: four projections of the same 3D world, blended with a 360 degree roll for"],["b+","the shift."],["b","5. audio.js: all sound synthesised with Web Audio."],["b","6. ui.js: keyboard, controller and touch input, intro, menus, HUD, saves."],"",["p","Bugs worth remembering:"],["b","The autopilot flew into walls because it assumed it would travel in a straight line to"],["b+","its target, while the ship really moves at full speed on both axes at once. Predicting"],["b+","per axis fixed it."],["b","Key taps shorter than one frame were lost. Input now latches a press until it has been"],["b+","read."]]},{"title":"5. SOUND AND STORY","lines":[["q","'dont forget high score and combo systems, floating combat text, announcer voiceover,"],["q+","fanfare for pickups and things, a toast upon level completion, liquid dnb music, lofi"],["q+","during menus ... storyline about defending earth from a cosmic shift'"],"",["b","Liquid drum and bass in flight, lo-fi on the menus, a darker roller for bosses, all"],["b+","sequenced in code."],["b","Announcer through the browser's speech voice."],["b","Story: a rift from Planet X is folding reality one world at a time."],"",["p","The Earth demo went live on ArcadeGridz the same morning."]]},{"title":"6. FIRST PLAYTEST, SECOND PASS","lines":[["q","'very cool ... in many ways its better than our original 2diso. it could use some"],["q+","tweaks'"],"",["p","The feedback list, and what changed:"],["b","'weapon upgrades are a little boring ... add wave weapon and a snaking lightning thing':"],["b+","SPEED left the bar. New bar: DRONE, SPREAD, LASER, WAVE, BOLT, MISSILE, SHIELD, ???."],["b+","Each weapon has named tiers. BOLT snakes round the screen and then homes in."],["b","'the starting weapon should shoot a bit slower': every weapon starts slow and speeds up"],["b+","with its own level."],["b","'god mode should do that super hyper beam thing': god mode fires a rainbow hyper beam,"],["b+","maxes every weapon and fills out five drones the borrowed drones leave when it ends."],["b","'tap it and it cycles between slow speed, default speed, and thrusted speed': B is now a"],["b+","three-speed gear, and SLOW is the default."],["b","'it should give you a little more time to shift': the world slows while you roll, the"],["b+","roll is quicker, hints come earlier."],["b","'walls that spawn during the first boss fight need more gridlines': boss sheets are"],["b+","dense grids, the safe gap is framed in green, and they charge for longer."],["b","'add a altitude bar': left edge of the HUD, with the blocked heights ahead in red and"],["b+","the way through in green."],["b","'the warp needs to be more hidden': each warp can only be reached from one view, and now"],["b+","leads somewhere."],["b","'do all the levels including bonus levels ... unique enemies/obstacles/bosses': Mars"],["b+","(geysers, fire arcs, magma worms, alien stone heads, THE COLOSSUS), Jupiter (lightning"],["b+","chains, storm walls, wraiths, THE EYE), Planet X (tentacles, membranes, spores, THE"],["b+","SHIFTER), and bonus stages on the Moon, the Sun, the Asteroid Belt and Pluto."],["b","'the hyperspace segway ... should swap through all the views': every level opens by"],["b+","rolling through TOP, CHASE and ISO before handing over in SIDE."],["b","'more neon tube light glows': every line is drawn as a tube: wide halo, glow, bright"],["b+","core."],["b","Level select from the solar map, for testing."]]},{"title":"7. SECOND PLAYTEST, QUICK FIXES","lines":[["q","'you made the walls that spawn during first boss actually harder to see not easier'"],"",["p","True. The new boss walls only drew their top and bottom faces, and in the 2D side view those"],["p+","are edge-on, so each wall collapsed into one line. Every face is now cross-hatched and the"],["p+","gap is boxed in green with chevrons."],"",["q","'mars boss should be more like an alien easter island type statue thing ... with"],["q+","smaller heads scattered throughout the level as enemies'"],"",["b","The Mars boss is now THE COLOSSUS, a giant alien stone head rising out of the ground."],["b+","Its attacks: eruptions under you, a rising lava tide and falling ash, then rings of"],["b+","fire."],["b","Smaller stone heads run through the level: sentinels planted in the ground that lob"],["b+","fire, floating heads that stare you down, and statue pillars to weave between."],["b","Sun bonus: the shadow lane is a dense blue hatch with bright rails, the screen glows"],["b+","hotter as you cook, and the flares are fans of wavy tendrils."],["b","BOLT has a much longer lightning tail."]]},{"title":"8. SOLID SHAPES AND THE ARENAS","lines":[["q","'add textures/gradient fills / shading / shadows to obstacles so we can see if it"],["q+","looks better or worse'"],"",["b","Obstacles can be drawn solid: dark shaded faces, a ground shadow, and the lines behind"],["b+","them hidden so the scene reads cleanly. It is an option (SOLID OBSTACLES) so both looks"],["b+","can be compared."],"",["q","'can we weave in an arena between levels that you have to clear a few waves in ..."],["q+","that would match the theme of the level you just cleared'"],"",["b","After every boss there is now a bonus arena: GRID ZERO, THE CRUCIBLE, EYE OF THE STORM"],["b+","and THE HEART. Free movement inside a walled grid, auto-aim at the nearest target, five"],["b+","waves and a champion."],["b","SHIFT still matters: L/R flips the arena between TOP and ISO, and the white enemies can"],["b+","only be hit in ISO."],["b","Each arena carries its planet's hazard (geysers on Mars, lightning on Jupiter, and so"],["b+","on). Losing your shield ends the bonus without costing a life."]]},{"title":"9. THE 'MAKE IT MORE IMPRESSIVE' PASS","lines":[["q","'do you have any other suggestions for improvements or features for the game to make"],["q+","it more impressive?' ... 'ok do all that stuff.'"],"",["p","Nine ideas went on the list and all nine went in, plus one more from Benjamin."],"",["b","Perfect Shift. Roll out of the way of something that was about to hit you and the fold"],["b+","bites back: a shockwave, a few seconds of overdrive and a score bonus. The theme is now"],["b+","the skill."],["b","Boss finishers. A dying boss comes apart in slow motion while the camera rolls through"],["b+","all four views."],["b","Twin-stick arenas. Right stick or mouse aims in the arenas. Auto-aim stays as the"],["b+","fallback, so a pad without sticks still works."],["b","A track per planet. Earth keeps the liquid roller, Mars gets a heavy half-time stomp,"],["b+","Jupiter fast arpeggios, Planet X a detuned whole-tone crawl, plus arena and bonus"],["b+","tracks. All still synthesised."],["b","Medals and ranks. Six medals per planet (clear, no ships lost, untouched, warp found,"],["b+","chain 50, three perfect shifts) and a rank from D to SS, shown on the solar map."],["b","Daily Run. One seed for everybody each day, with one helpful and one hurtful twist"],["b+","picked from the date. No continues."],["b","Best-run ghost. The simulation is deterministic, so a run is just a seed, a loadout and"],["b+","the inputs. Your best run of each planet flies next to you as a ghost."],["b","Screen effects. Colour split on shifts, extra shock rings on big kills, an optional CRT"],["b+","filter."],["b","Two-player co-op. Two ships, one shared upgrade bar. Player one on keyboard, player two"],["b+","on a controller (or two controllers)."],"",["q","'we can also do rivet-9 assist toggle too' ... 'it will be cool to see what rivet 9"],["q+","looks like when he shift perspectives before we do'"],"",["b","RIVET-9 assist. RIVET-9 is the ArcadeGridz house AI. Switch him on and he flies as your"],["b+","wingman with a light gun. Runs with him are tagged ASSISTED. The first version had him"],["b+","roll into the next view before you did, drawn in that view."],"",["q","'forget having rivet 9 switch perspectives before us it looks funky and illogical lol."],["q+","just have him do it when we do.'"],"",["b","He now rolls when you roll."],["b","Weak spots. Every boss core carries a hatched, pulsing gold target when it can be hurt"],["b+","and a dim red cross when it is shielded."],["b","Easier to read shots. The main gun fires thicker bolts, the laser has a wide glow, and"],["b+","enemy bullets are bigger spinning rings with a white core and a tail."],["b","A further horizon. Buildings, walls and other scenery are placed much further out and"],["b+","fade in, so nothing pops up in your face."]]},{"title":"10. THIRD PLAYTEST","lines":[["q","'tone down the speed on the obstacles spawning on the first boss again ... if a"],["q+","upgrade is maxed out it should skip it ... i still cant seem to get the warp to work'"],"",["b","First boss, slower again. OVERSEER's walls come about a third less often, charge for"],["b+","longer and leave wider gaps. Its bullets and thrown gates are slower too."],["b","Three ranks per weapon. SPREAD, LASER, WAVE, BOLT and MISSILE now max at 3 instead of 5."],["b+","The weak early ranks are skipped, so rank 3 is still the full effect. Drones go up to 6."],["b+","Boss health went up to match."],["b","The bar skips what is maxed. A pod never lands the highlight on a full slot."],["b","Pods are gold and blue."],["b","God mode is one beam. A single thick hyper beam that fires on its own in explosive"],["b+","pulses."],["b","Warps you can actually take. Each warp now fades in during the calm opening stretch of a"],["b+","level and hangs in front of you for about fifteen seconds before it fades out. In the"],["b+","flat views it is only a flickering sliver. Roll into CHASE view and it opens into a ring"],["b+","you can fly through."],["b","Missiles you can see. Finned rockets with smoke trails, a blast on every hit."],["b","Menus. Holding a button no longer presses a menu item over and over. SAVE AND QUIT now"],["b+","saves the exact spot instead of the last checkpoint."]]},{"title":"11. FOURTH PLAYTEST: EVERY PLANET ITS OWN","lines":[["q","'each boss needs its own unique mechanics ... the levels need more of their own unique"],["q+","level themed mechanics too. not just giant boxes that get in the way'"],"",["b","Bosses stop sharing tricks. The grid walls and thrown gates now belong to OVERSEER"],["b+","alone."],["b","THE COLOSSUS ends with widening rings of fire that have one gap."],["b","THE EYE is new from top to bottom: lightning that walks down the lane behind warning"],["b+","rings, a stare that locks onto your height and fires, a cyclone that drags you in while"],["b+","spiral arms of sparks sweep the deck, and storm orbs that circle the pupil and soak up"],["b+","shots."],["b","THE SHIFTER throws walls of mutant blobs you have to burst, and rows of tentacles that"],["b+","erupt along whole lanes."],["b","The camera pulls back for bosses."],["b","Earth: neon billboards to shoot down, freight lifts riding between the skyways, blinking"],["b+","laser fences, cross traffic between the towers, and a second, faster stream of hover"],["b+","traffic with buses."],["b","Mars: rivers of lava that wander across the floor, lavafalls that pour and stop, basalt"],["b+","boulders to blast, boulders that roll."],["b","Jupiter: drifting fog banks, ammonia ice that grows across the one open lane, wandering"],["b+","tornadoes, floating storm buoys that shoot."],["b","Planet X: blob walls to burst, spore pods that pop into rings of acid, long tentacles"],["b+","that whip right across the forest."],["b","Upgrade bar: MISSILE and SPREAD swapped places, so the screen does not fill with spread"],["b+","shots early."],["b","A shorter title menu. PLAY, OPTIONS, HIGH SCORES, DEVLOG, EXIT GAME. Continue, New Game"],["b+","and Co-op live under PLAY. The solar map is still in the pause menu. The Daily Run is"],["b+","shelved."],["b","The map before every hop. Going to the next planet, into a bonus stage or back out of"],["b+","one, the solar map comes up first and the ship flies from where you are to where you are"],["b+","going. Then hyperspace."],["b","Speed. Jupiter and Planet X were dropping frames. Faint lines, sparks and smoke no"],["b+","longer get the expensive glow passes, and the game now steps its own quality down if"],["b+","frames run long."]]},{"title":"12. FIFTH PLAYTEST","lines":[["q","'add a bonus that affects rank based on how fast you beat it because maybe sometimes"],["q+","people are changing their speed'"],"",["b","Time counts. Every planet has a par time. Beat it for a FAST CLEAR medal (a seventh"],["b+","medal, so the top rank is now SSS), and the faster you finish the bigger the time bonus."],["b+","Flying the whole level at slow speed will not make par."],["b","Progress bar. A bar under the view tabs shows how far through the level you are, with"],["b+","the checkpoints marked."],["b","The ship leans. It banks when it slides sideways and noses up or down when it climbs or"],["b+","dives."],["b","Weapons grow differently."],["b","LASER is one beam that gets thicker and hits harder with each rank, instead of extra"],["b+","rows."],["b","MISSILE keeps two up front and adds rockets out of the back: two at rank 2, four at rank"],["b+","3."],["b","SPREAD covers your tail with two rear shots at max rank."],["b","BOLT fires one bolt at a time, faster with each rank."]]},{"title":"13. SIXTH PLAYTEST","lines":[["q","'those box looking obstacles dont really make any sense in any level except the first"],["q+","one. you need to improvise different shapes and landscapes for the other levels'"],"",["b","No more crates off Earth. The same obstacles are now drawn as ragged rock outcrops on"],["b+","Mars, scalloped cloud banks on Jupiter and quivering slabs of tissue on Planet X. Earth"],["b+","keeps its buildings."],["b","More to shoot. Every planet has roughly half again as many enemy waves, with divers"],["b+","between the flights."],["b","A wider view. The whole game is zoomed out a notch, and bosses pull the camera back"],["b+","further still."],["b","The Eye's beam makes sense now. It turns to follow you, holds still for a moment, then"],["b+","fires one big beam straight out of its pupil."],["b","Lightning chains read in every view. Seen end-on in the flat views they used to be a"],["b+","dot. Now they crackle."],["b","Solid bosses. Each boss has a shaded body behind its wireframe."],["b","The shield hugs the hull. One outline around the ship per layer, up to three."],["b","Mars, again. The lavafalls are thick, rippling curtains now, there are more rivers of"],["b+","lava, and THE COLOSSUS was re-cut so it reads as a giant stone head from every side:"],["b+","flat top with a topknot stone, a heavy brow shelf, a long nose, pursed lips, a jutting"],["b+","chin, long ears and buried shoulders."],["b","Pods always pay. Buying anything is worth 500 points, so pods still matter when"],["b+","everything is maxed."],["b","A lost ship takes its weapons with it. Drones stay, the guns start over. It was too easy"],["b+","to max everything by the middle of the second planet and never look back."]]},{"title":"14. SEVENTH PLAYTEST: BUSIER, WIDER, EASIER TO READ","lines":[["q","'the levels should be really busy but with enough time to react to everything'"],"",["b","Wider and taller. The lane is a little wider and higher, and the camera sits further"],["b+","back again, in levels and in boss fights."],["b","Far backgrounds. Every planet has a distant layer now: a lit skyline with searchlights"],["b+","on Earth, volcano ranges with smoke plumes on Mars, drifting cloud belts and a great"],["b+","storm on Jupiter, swaying stalks with eyes on Planet X. Plus a moon or neighbouring"],["b+","world in every sky."],["b","Earth looks like a city. Buildings have lit windows and blinking masts. The skyways are"],["b+","truss bridges with running lights."],["b","More of everything. More enemy flights on every planet, small things to blast in the"],["b+","gaps, and ground troops: tracked guns on Earth and Jupiter, legged crawlers on Mars and"],["b+","Planet X, on the floor and sometimes the ceiling."],["b","Missiles hug the walls. They are no longer homing: one goes up and one goes down, then"],["b+","they run along the ceiling and the floor. In top view they run along the side walls."],["b+","That makes them the answer to ground troops. The bolt is still the homing weapon."],["b","More time to shift. The call to change view comes earlier, nothing solid sits around a"],["b+","change of view, and if the view you need is two rolls away a single press takes you"],["b+","straight there. The L or R that gets you there lights up."],["b","Boss walls fade in. They start as a ghost and firm up gradually, and only blink in the"],["b+","last moment."],["b","Catching up. Losing a ship drops a few pods (more in a boss fight), and bosses throw a"],["b+","pod now and then."]]},{"title":"15. ARENAS AND MINIBOSSES","lines":[["q","'the in between level bonus arena can be zoomed out quite a bit more and the arena"],["q+","made larger and instead of autoaiming it should shoot the direction you are facing as"],["q+","you move around'"],"",["b","A bigger arena, seen from further back. The floor is about twice the area and the camera"],["b+","pulls well back. The waves are bigger to match."],["b","You aim by flying. The guns fire the way the ship faces, and it faces the way it moves."],["b+","A right stick or the mouse still aims on its own if you have one."],["b","A miniboss ends every arena. GRID WARDEN patrols a square circuit sweeping four rotating"],["b+","streams. STONE ELDER marks where you stand, leaps there and lands in a ring of fire."],["b+","THUNDER BLOOM drifts after you trailing spiral arms and calls lightning down. BROOD"],["b+","MOTHER hatches spores and spits fans of acid, faster as she weakens."],["b","A miniboss ends every warp stage too. LUNAR SENTINEL, SOLAR FLARE, THE MOTHER ROCK and"],["b+","FROST WARDEN. The stage only clears once it is gone."],["b","Minibosses scale with you. They are as tough as your guns are strong."],["b","Clearing every wave pays more: 15,000, on top of 5,000 for the miniboss. Dying in an"],["b+","arena still only ends the arena."],["b","Hover traffic you can read. On Earth the cars are colour-coded by height (green low,"],["b+","yellow middle, pink high), each one drops a line to a shadow on the ground, and the"],["b+","altitude meter shows the traffic ahead at its height. There are also about twice as many"],["b+","rows of it."]]},{"title":"16. AN ENDING, A CREDIT ROLL, A LOOP, ACHIEVEMENTS AND TARGET ORDER (R22)","lines":[["p","BDC beat THE SHIFTER and nothing much happened. This revision gives the game an end, and a"],["p+","reason to keep going."],"",["b","A real ending. Planet X folds shut, the worlds you saved come back one at a time and the"],["b+","ship flies home. Then something stirs past Pluto."],["b","Planet X now has its arena too. THE HEART and the BROOD MOTHER come after THE SHIFTER,"],["b+","and the ending follows them."],["b","Movie credits. They roll slowly up the screen while the ship and RIVET-9 swoop through"],["b+","in wide figure-eights. Hold the button to speed them up."],["b","Loop the game. After the credits you can start again at Earth with every upgrade and"],["b+","your whole score. The save remembers which loop you are on."],["b","Achievements. Thirty of them, with their own entry on the title menu. They are kept on"],["b+","your device, and idle mode never unlocks them."],["b","Target order. Shoot one of a wave and the next one gets a target on it. Finish the whole"],["b+","wave in that order for a bonus of 300 a head."],["b","Calmer missiles. Smaller rockets, about half as often, less smoke, and never more than"],["b+","two out of the back. Each one hits harder to make up for it."]]},{"title":"17. LOOPS THAT BITE BACK (R23)","lines":[["p","BDC's order: loop 2 significantly harder, loop 3 extremely difficult, loop 4 borderline"],["p+","impossible."],"",["b","Every loop: enemies are tougher (1.7, 2.6, then 4 times the health), their shots are"],["b+","faster, everything that flies now shoots, and it shoots back when it dies."],["b","Hunters. Red divers come at you all level long, more often each loop."],["b","The scroll speeds up: 15, 30, then 50 percent faster."],["b","Bosses shoot at you too, in wider fans each loop, on top of their own attacks."],["b","Shields fade. On loop 3 one hit strips every layer. On loop 4 shields do nothing."],["b","Past loop 4 the enemy just keeps getting tougher."]]},{"title":"18. THE WAVE IS A WAVE (R24)","lines":[["b","One wave, not several. The wave weapon is now a single stream that snakes out of the"],["b+","ship along a sine curve, drawn as a glowing ribbon with a white-hot core and a trail of"],["b+","sparks."],["b","Upgrades wind it up. Each rank tightens the frequency, swings it wider and hits harder,"],["b+","and the colour climbs from cyan to violet to hot pink. No extra waves above or below the"],["b+","ship."],["b","It still passes through walls, and it ripples slowly so the curve never sits still."]]},{"title":"19. CLEAN RESULTS SCREENS (R25)","lines":[["b","GAME OVER and the clear screens now hide the HUD, so nothing overlaps the results. The"],["b+","level keeps running behind them, a little brighter than before."]]}]},{"name":"DAY 2","entries":[{"title":"20. ENEMIES YOU CAN WATCH DIE (R26)","lines":[["p","BDC's note: everything was dying in one shot before you even noticed it."],"",["b","Twice the health on every ordinary enemy. Bosses and minibosses are unchanged."],["b","Health bars appear over anything that is being hit and fade a moment later."],["b","Damage numbers float off whatever you are hitting, in small batches so they stay"],["b+","readable. Score numbers still float up on a kill."],["b","A wider view again. The camera sits further back in levels, and further still for bosses"],["b+","and arenas."]]},{"title":"21. TOUGHER STILL, A SLOWER PACE AND A FOURTH SPEED (R27)","lines":[["b","Enemy health scales with your guns. Doubling it was not enough once the weapons were"],["b+","built up, and a flat four times starved a fresh ship of kills and pods. So ordinary"],["b+","enemies now start at 1.6 times their old health and climb as you upgrade: about four"],["b+","times by mid-game, just over five at full power."],["b","The levels move slower, and there are four speeds now: SLOW, CRUISE, FAST and TURBO."],["b+","Slow is about a sixth slower than it was turbo is the old top speed. Par times are"],["b+","longer to match."],["b","Changing speed is called out. SHIFTING UP or SHIFTING DOWN shows over the ship with the"],["b+","new speed, and the announcer says it."]]},{"title":"22. TRAFFIC FROM BEHIND, AND A BUILDING SITE (R28)","lines":[["b","Hover traffic is a CHASE section now. BDC found it far more fun from behind the ship"],["b+","than from the isometric view, so the level calls for CHASE there."],["b","A construction zone takes the ISO slot on Earth. Half-built girders at every height,"],["b+","crane loads swinging across the lane on their cables, crate stacks to shoot through for"],["b+","gems and pods, and turrets on the ground. It sits between the firewall gates and the"],["b+","traffic, so the level is a little longer and its par time went up to match."],"",["img","shots/earth-construction.jpg","THE CONSTRUCTION ZONE ON EARTH, PLAYED IN THE ISOMETRIC VIEW",560,315]]},{"title":"23. ROOM TO FLY, A KINDER HITBOX, AND THINGS THAT LOOK LIKE WHAT THEY ARE (R29)","lines":[["b","The ship can fly much further forward. The forward limit moved out by two thirds, and"],["b+","bosses hold further back near the edge, so there is more room to read their attacks."],["b","A smaller hitbox. Only the hull counts now. Wing tips and the tail pass through things,"],["b+","so a car you have already cleared no longer clips you from behind."],["b","Hits flash red. Enemies and bosses blink red for a split second when a shot lands."],["b","Earth's obstacles are drawn as what they are. Hover cars are wedges with a glass canopy,"],["b+","headlights, tail lights and hover pads buses are long slabs with a row of windows."],["b+","Girders are yellow I-beams with rivets and hazard stripes, slung on cables or stood on"],["b+","posts. Cranes are lattice masts with a cab, a jib out over the lane and a counterweight"],["b+","their loads hang on four slings and a hook. Crates have straps, and the wider towers get"],["b+","a rooftop pad."],["b","The Sun stage has solar satellites. The shade lanes are now the panels of satellites,"],["b+","each with a gold body, a dish and antennas."],["b","Solar flares. Big bright prominences loop up off the surface and whip across the lane,"],["b+","five in the first half and four in the second."],["b","A fix on the Sun. The heat kept climbing during the miniboss, after the last shade had"],["b+","gone, so the stage could end there through no fault of yours. The heat now stops once"],["b+","the miniboss arrives."]]},{"title":"24. NOTHING OFF EARTH IS A BOX (R30)","lines":[["p","The second half of BDC's note from r29: smoother, more organic shapes on the other worlds."],"",["b","Mars, Jupiter and Planet X. Every plain obstacle is now drawn as a rounded body with a"],["b+","flat foot where it meets the ground or the roof: chamfered boulders with facet lines on"],["b+","Mars, scalloped cloud banks on Jupiter, bulging tissue that breathes on Planet X. Seen"],["b+","from above they are rounded outlines with an inner contour, not rectangles."],["b","Asteroids and boulders use a new lumpy twelve-point rock in place of the old diamond,"],["b+","and Mars boulders lost the square behind them."],["b","Ice is cut stone. Small ice blocks are irregular gems with facets, the Pluto shelf is a"],["b+","jagged sheet with cracks, and Pluto's spires are six-sided crystal shafts drawn to a"],["b+","point."],["b","Bigger solar flares. Wider strands, thicker glow, a slower sweep and a bigger hitbox to"],["b+","match in the first half of the Sun stage."]]},{"title":"25. CENTRED VIEWS, LAVA THAT CROSSES YOUR PATH, AND ARENAS WITH A FLOOR WORTH LOOKING AT (R31)","lines":[["b","The view is centred again. Pulling the camera back had left dead space at the bottom of"],["b+","the top-down view and down the left of the side view, most obviously in the arenas. Each"],["b+","view now zooms out from its own anchor, so the field sits between the HUD and the"],["b+","upgrade bar. The side view also pulls back a little less than the others."],["b","Mars lava rivers flow across the lane. They are wide, they stream sideways, and they no"],["b+","longer block. Instead the lava drags the ship to a crawl and fills a heat meter: cross"],["b+","one at the slowest speed and you overheat and take a hit. Shift up, or dash forward, and"],["b+","you get through with heat to spare."],["b","Arena floors belong to their planet. Earth is a circuit board with pulses running down"],["b+","the traces. Mars is a cracked crucible with glowing fissures, lava at both ends and"],["b+","braziers in the corners. Jupiter is a slowly turning storm spiral ringed with cloud."],["b+","Planet X is a beating heart with veins running out to eye stalks."]]},{"title":"26. THE REAL LOGOS (R32)","lines":[["b","The opening GRiDDiM and ArcadeGridz screens now show the actual logos when their image"],["b+","files sit beside the game (src/logo-griddim.png and src/logo-arcadegridz.png). On"],["b+","ArcadeGridz they do. Where the files are missing the game falls back to the drawn"],["b+","versions, so nothing breaks."]]},{"title":"27. A SLEEKER FONT, SHOTS THAT STOP, A LEANER GUN, AND WORLDS WITH LESS GRID (R34)","lines":[["b","The font. Every corner of every letter is now rounded and the whole face leans slightly,"],["b+","so it reads as bent neon tube instead of calculator segments. The zero lost its slash."],["b","Hits keep flashing. Enemies and bosses strobe red while they are under continuous fire,"],["b+","where before they just stayed red."],["b","Shots stop at what they hit. Bullets, the laser, bolts and missiles are all spent on the"],["b+","first enemy or obstacle in their way. Only the wave and the god-mode pulse still pass"],["b+","through. The laser and the main gun hit harder to make up for it."],["b","The main gun fires one bullet. SPREAD now upgrades it: three ahead, then three ahead and"],["b+","one behind, then three ahead and three behind."],["b","Mars has ground, not a grid. Cracked, uneven terrain with rocks and craters, in the"],["b+","level and in its arena."],["b","A cave on Mars. A new ISO section between the fire arcs and the magma tubes: rock spikes"],["b+","rising from the floor and hanging from the roof, pillars, and rocks that let go of the"],["b+","ceiling as you get near and smash on the floor. A red ring on the ground marks where"],["b+","each will land."],["b","More city on Earth. Infill blocks and antenna masts in the opening stretch, extra towers"],["b+","and signs between the rows in the top-down section, and more on the skyways."],["b","Jupiter's cloud is a net. Three layers of fine wavy mesh drift past underneath at"],["b+","different speeds, with one more overhead, and the cloud banks themselves have a soft net"],["b+","of threads across them."],"",["img","shots/mars-caves.jpg","THE MARS CAVES: TERRAIN, SPIKES AND FALLING ROCK INSTEAD OF A GRID",560,315],"",["img","shots/jupiter-nets.jpg","JUPITER: FINE WAVY NETS FOR CLOUD LAYERS",560,315]]},{"title":"28. THE BOSS HEALTH BAR IS BACK (R35)","lines":[["b","When the bosses were moved further back in r29, the boss health bar and the weak-spot"],["b+","marker were still waiting for the boss at its old distance, so neither ever appeared."],["b+","Both now show again and the bar drains as the boss takes damage."]]},{"title":"29. ARENA WARPS, A MAP THAT KEEPS SCORE, AND CALMER LAVA (R36)","lines":[["b","Arenas are found, not handed out. A planet's bonus arena no longer follows its boss."],["b+","Each level now hides a second warp, a gold one with no announcement, a little after the"],["b+","first checkpoint. Fly into it from CHASE view and you fight the arena win or lose, you"],["b+","are dropped back at the next checkpoint of the level you left."],["b","Space stations on the solar map. Each arena is a small station tethered under its"],["b+","planet, shown as a question mark until you find its warp. The ship flies to it and back"],["b+","on the map, the same as for the other bonus stages."],["b","Ticks and grades. Cleared planets get a green tick and their rank on the map cleared"],["b+","bonus stages and arenas get a tick."],["b","The lava tide rolls. The rising lava and falling ash in THE COLOSSUS fight now have a"],["b+","proper wave running along the surface and through the layers beneath it."],["b","No more lava lines. The flickering lines over the nearby volcanoes are gone. Far-off"],["b+","volcanoes now spit blobs of lava that arc up and fall back."]]},{"title":"30. THE GROUND IS NOT FLAT (R37)","lines":[["b","Hills, slopes and ramps. Every planet now has stretches where the ground rises, levels"],["b+","off and falls away: overpasses and embankments on Earth, dunes and ridges on Mars (one"],["b+","runs through the cave), swells in Jupiter's cloud deck, mounds of tissue on Planet X."],["b","The ship rides over them. A hill does not kill. It lifts the lowest height you can fly"],["b+","at, so there is less room under whatever is overhead. Ground troops stand on the slope."],["b","The floor follows the slope in every view. Side on, a hill is a bright ridge line with"],["b+","hatching beneath it."]]},{"title":"31. BOSS RUSH (R38)","lines":[["b","A new mode in the PLAY menu. Twelve fights back to back: each planet's boss, then its"],["b+","arena miniboss, then its warp-stage miniboss, from OVERSEER to FROST WARDEN. No results"],["b+","screens, no map and no story in between."],["b","How it starts each fight. Planets begin at the checkpoint just before the boss, bonus"],["b+","stages just before their miniboss, and arenas skip their waves. You start with a modest"],["b+","loadout and five ships, and carry upgrades, ships and score from fight to fight. Here a"],["b+","hit in a bonus stage costs a ship like anywhere else, not the whole stage."],["b","Score and time. A clock runs while you play and shows in the HUD with the fight number."],["b+","The end screen gives fights won, time and score, and your best run is kept and shown in"],["b+","the PLAY menu. Beating all twelve unlocks a new achievement, GAUNTLET."],["b","Also fixed: the WEAPONS LOST callout when you lose a ship had been silently switched off"],["b+","by a stray comment."]]},{"title":"32. EXTRA SHIPS (R39)","lines":[["b","1UP pickups. Enemies now sometimes drop an extra ship: a small green ship turning inside"],["b+","a purple ring with a plus sign beside it. They are rare, but one is always due after"],["b+","enough kills, so every level should show at least one. Picking it up adds a ship (up to"],["b+","nine) with a '1UP!' callout at nine it pays 5000 points instead."],["b","Ship counter. The HUD still shows six ship icons, with a '+N' beside them when you hold"],["b+","more."],"",["img","shots/extra-ship-pickup.jpg","AN EXTRA SHIP PICKUP BESIDE A FIREWALL GATE IN CHASE VIEW",560,315]]},{"title":"33. BOMB UPGRADES, A BIGGER PLAYFIELD AND TWO SHIP SKINS (R40)","lines":[["b","Bombs upgrade. The power-up bar has a new BOMB slot with three tiers, so spare pods have"],["b+","somewhere to go. The basic bomb is now a short burst around the ship. Tier 1, SWEEP"],["b+","BOMB, is a rectangle that rolls out from the ship over a much bigger area. Tier 2,"],["b+","SCATTER BOMB, sets off eighteen diamond blasts across the screen, half of them on"],["b+","enemies. Tier 3, MEGA NUKE, pulls everything in for half a second and then takes out the"],["b+","whole screen. The tier survives losing a ship, like drones do."],["b","More room. The camera is in effect 30% further back with the levels 30% bigger to match:"],["b+","the ship, enemies, shots and pickups are all drawn and collide about a quarter smaller"],["b+","against the same level layouts. Gaps, lanes and gates are that much roomier and"],["b+","buildings that much taller next to the ship. Drone formations, the wingman and the"],["b+","idle-mode pilot were resized to match."],["b","Taller skyline. Earth's opening run has taller and more varied towers, with blocks"],["b+","hanging from above where the tower below is short."],["b","Hit flash. The red flash on enemies and bosses strobes slower and lasts longer, so it"],["b+","reads as a flash when you are pouring fire in."],["b","Ship skins. OPTIONS has a SHIP SKIN setting. FIRE MAGE turns the ship into a firebat"],["b+","with flapping wings and embers, and every weapon into fire: flame darts, a wavering"],["b+","stream of flame, fireball missiles, ember drones. DARK LORD is a wraith stealth ship"],["b+","trailing a ragged cloak, with shadow bolts, a violet beam, soul-green lightning and"],["b+","wisps for drones. Skins only change the look. FIRE MAGE unlocks by beating the second"],["b+","boss and DARK LORD by beating the last one the options menu previews a locked skin on"],["b+","the title screen."],"",["img","shots/bomb-sweep.jpg","TIER 1, THE SWEEP BOMB, ROLLING OUT FROM THE SHIP",560,315],"",["img","shots/bomb-scatter.jpg","TIER 2, THE SCATTER BOMB",560,315],"",["img","shots/bomb-mega-charge.jpg","TIER 3, THE MEGA NUKE, PULLING IN BEFORE IT GOES OFF",560,315],"",["img","shots/skin-fire-mage.jpg","THE FIRE MAGE SKIN WITH EVERY WEAPON FIRING",560,315],"",["img","shots/skin-dark-lord.jpg","THE DARK LORD SKIN WITH EVERY WEAPON FIRING",560,315]]},{"title":"34. SEEING FURTHER, HYPERDRIVE AND SET-AND-FORGET BOMBS (R41)","lines":[["b","See further ahead. The last pass made room around the ship but showed no more of the"],["b+","level ahead, which was the point of asking. Now the distance ahead is squeezed on screen"],["b+","by the same 30%, so about a third more of the level is in view in every view, and the"],["b+","ship can fly a third further up it. Enemies and scenery are placed that much further out"],["b+","so nothing appears inside the picture. Ships, enemies and rings are stretched back so"],["b+","they keep their shape. Boss fights and arenas keep their own camera."],["b","Hyperdrive. The wildcard slot at the end of the bar is gone. In its place is HYPER,"],["b+","which stays locked until drones, every weapon and the bomb are maxed. One pod then"],["b+","switches hyperdrive on for good: 15% more damage from everything, kept when you lose a"],["b+","ship, and the ship glitters while it is on."],["b","Auto detonate. A new option sets off a bomb every ten seconds for as long as you have"],["b+","one."],["b","Back to slow. Losing a ship drops the speed back to SLOW, so the next one is not thrown"],["b+","straight into traffic."],["b","Red targets. The target marker on the next enemy in a wave is red now in yellow it"],["b+","looked too much like a pickup."],["b","Skins in the store. FIRE MAGE and DARK LORD can now also be bought with Sparkz in the"],["b+","site's store, as well as earned by beating the bosses."],"",["img","shots/view-top-further.jpg","A THIRD MORE OF THE LEVEL IN VIEW, HERE FROM ABOVE",560,315]]},{"title":"35. A BUG TEST CHECKLIST (R42)","lines":[["b","BUG TEST. The title menu and the pause menu have a BUG TEST checklist: every planet,"],["b+","warp stage and arena, Boss Rush, and the ending with its loop. Picking one starts you"],["b+","there with no damage: hits are marked on screen and counted, but nothing is lost, so the"],["b+","weapons and upgrades behave as in a real run and you buy them by hand. Planets start"],["b+","with roughly the loadout you would have by then. Clearing one ticks it off, and the list"],["b+","is kept between sessions."],["b","Clean test runs. Test runs never post scores and do not unlock achievements, skins,"],["b+","medals, ghosts or Boss Rush records."],["b","One switch for release. When the list is done, a single flag hides the checklist and the"],["b+","solar map's level-jump test buttons together for the jam build."]]},{"title":"36. A NEW VOICE (R43)","lines":[["b","The announcer is a woman now. A calm, close, unhurried voice, picked from the best"],["b+","female voice the browser offers, a little lower and slower than normal speech."],["b","Title voiceover. The title screen says the name: 'two-diso ... shift'."],["b","ISO is a word. The announcer used to spell out I-S-O it now says 'eye-so', like the rest"],["b+","of us."]]},{"title":"37. TEST TOOLS: ANY SKIN, ANY LOADOUT (R45)","lines":[["b","Skin picker in BUG TEST. Wear any skin for testing, locked or not. It only works while"],["b+","the test menu exists, so it goes away with it."],["b","Loadout manager in BUG TEST. Set drones, each weapon, bomb tier, hyperdrive, shields,"],["b+","bombs and ships by hand every test, Boss Rush included, starts with that loadout. MAX"],["b+","EVERYTHING and EMPTY are one press each."],["b","A shorter pause menu. Idle mode and the RIVET-9 assist only live in OPTIONS now."]]},{"title":"38. A NEW LOGO (R46)","lines":[["b","A display face of its own. The title logo is no longer set in the in-game font. It has"],["b+","its own geometric letters, built from chamfered strokes with a dark keyline, a hot core"],["b+","and a chrome gradient. 2DISO leans a little in cyan and blue SHIFT leans hard in pink"],["b+","and violet."],["b","SHIFT is sliced. A seam runs through SHIFT and its top half sits shifted sideways, as if"],["b+","the view was caught mid-roll. Every couple of seconds it jolts further."],["b","New tagline. 'Shift the view. Shift the rules.'"]]},{"title":"39. PILL BUTTONS, A FIFTH SPEED AND A FAIRY (R47)","lines":[["b","Menus look like the site. Menu items are neon pill buttons, as on ArcadeGridz and in the"],["b+","app: a cyan outline at rest, the chosen one lit amber and lifted. Option rows show their"],["b+","left and right arrows inside the lit pill. The title menu floats over the attract run"],["b+","with no box behind it, and other menus sit on a soft rounded glass card."],["b","A bolder menu font. Menu items and titles use a new bold style of the vector font: thick"],["b+","strokes, corners cut square instead of rounded, a bit more lean and more room per"],["b+","letter."],["b","HYPER. A fifth speed above TURBO, for going very fast."],["b","The god-mode beam reaches the far edge of the bigger field again, and so do the laser"],["b+","and the drones' beams."],["b","The wave hits harder (about half as much again at every rank), and its top rank is gold"],["b+","so it no longer looks like rank 2. The skins got the same fix."],["b","The title voice says it right: 'two-DIE-so', a beat, then 'shift'."],["b","A cooler tagline. Under the logo it is now bold and in two colours, 'SHIFT THE VIEW' in"],["b+","cyan and 'SHIFT THE RULES' leaning in pink, with a lit chevron between them and brackets"],["b+","either side."],["b","PIXIE skin. The ship becomes a fairy: a glowing body, four butterfly wings that flutter,"],["b+","antennae and a falling trail of glitter. Shots become twinkling stars, missiles little"],["b+","spinning stars, drones fireflies, and every beam and wave turns pastel. Beat the Eye on"],["b+","Jupiter to earn it, or buy it in the Sparkz store."]]},{"title":"40. RED FOG, GAS CLOUDS AND A HYPER RUN (R48)","lines":[["b","The Sun, rebuilt. The solar panels are gone. The Sun's atmosphere is now thick red"],["b+","plasma fog with one clear winding channel through it stay in the channel to stay cool."],["b+","Solar flares are bigger, with five twisting strands, bright knots and glowing feet."],["b","Jupiter's gas clouds. Big clouds drawn as a fine wavy mesh drift by slower than the"],["b+","level, so enemies and obstacles slip behind them for a moment."],["b","Jupiter recoloured and longer. Greens, purples and fuchsia instead of brown, more"],["b+","enemies everywhere, and a new chase section, THE DEEP, full of sharks and jellyfish to"],["b+","dodge."],["b","Mars eruptions are now columns of fire instead of lines."],["b","Planet X hyper run. A section near the end locks you at HYPER speed. Walls flash where"],["b+","they are about to appear, then turn solid."],["b","Warnings. Some enemy waves flash on screen just before they arrive, and the gold warps"],["b+","now come with an ANOMALY DETECTED call and a hint, plus a slightly bigger catch area."],["b","Bosses call in waves of their level's enemies during the fight, and in chase view they"],["b+","are drawn bigger so you can see their faces."],["b","Solid enemies. Every enemy has a shaded body behind its outline, so nothing is just a"],["b+","pair of crossed lines any more."],["b","More hills and ramps on every planet, and the bonus stages lean on chase and iso views."],["b","Smoother. Quality steps down sooner when frames slow down and comes back once things"],["b+","settle."],"",["img","shots/sun-red-fog.jpg","THE SUN IN CHASE VIEW: DENSE RED FOG WITH ONE CLEAR WAY THROUGH",560,315]]},{"title":"41. RAGGED HOLES AND REAL BOULDERS (R49)","lines":[["b","No more square holes off Earth. In chase view a gate on Mars, Jupiter or Planet X is now"],["b+","one wall of rock, cloud or flesh with a ragged rounded opening, a tunnel rim, and"],["b+","cracks, ripples or veins spreading out from it. A soft green rim inside marks the way"],["b+","through. The opening is drawn slightly inside the real gap, so the edge never kills you"],["b+","before it looks like it should. Earth keeps its square building gaps."],["b","The Sun's fog is drawn the same way in chase and iso: slice after slice of red fog with"],["b+","a rounded hole for the channel."],["b","Rocks look like rocks. Rocks on every planet bulge in the middle and taper front and"],["b+","back instead of being extruded blocks, with round shaded lobes instead of box fills. The"],["b+","Moon trench is now a ragged line of boulders of different sizes instead of a row of"],["b+","cubes."],"",["img","shots/gate-ragged-hole.jpg","PLANET X: ONE WALL OF TISSUE WITH A RAGGED OPENING INSTEAD OF A SQUARE GAP",560,315],"",["img","shots/sun-fog-slices.jpg","THE SUN FOG DRAWN AS SLICES WITH ROUNDED HOLES",560,315]]},{"title":"42. RIVET-9 ON COMMS (R50)","lines":[["b","Tips come from RIVET-9. View calls, hazard tips and anomaly alerts now pop up as a"],["b+","little instant-message window in the top left, with his portrait, a title bar and the"],["b+","text typing out. It stays up long enough to read, fades away on its own, and he reads it"],["b+","out loud. If a second message comes in, the first slides down and fades."],["b","He overreacts, on purpose. His face is an emoji on a visor and changes as he talks:"],["b+","shocked then starry-eyed at an anomaly, panicking with a sweat drop at lava, sharks and"],["b+","lightning, angry eyebrows at a boss, a smug grin when it's time to shift. His mouth"],["b+","flaps while the words come out, he shakes when he's scared, and every message opens with"],["b+","WHOA!!, YIKES!, GET HIM! or OOH!"],["b","The big calls stay big. Stage names, waves and other headline calls stay as"],["b+","centre-screen banners, now in the thick bold font along with the level titles, results"],["b+","screens, boss names, warnings and score pop-ups."],"",["img","shots/rivet-comms.jpg","RIVET-9 PANICKING ABOUT SHARKS IN THE TOP LEFT CORNER",560,315]]}]},{"name":"DAY 3","entries":[{"title":"43. WARPS YOU HAVE TO MEAN (R51)","lines":[["b","On Earth the arena warp could still be hanging around when the level asked you to shift"],["b+","to chase view, so you could fall into it by accident and skip a good stretch. Every warp"],["b+","now appears in a stretch that isn't played in chase view, and closes before the next"],["b+","chase stretch, so taking one is always a choice."]]},{"title":"44. BOSS RUSH WARP STAGES FIXED (R52)","lines":[["b","In boss rush the four warp stages said complete straight away. Boss rush dropped you in"],["b+","just past the point where the miniboss is called in, so it never came. Boss rush now"],["b+","looks up where each stage's miniboss arrives and starts you just before it."],["b","The red HIT markers from bug testing are gone. Bug test still counts your hits on the"],["b+","results screen."]]},{"title":"45. TABS, SURPRISE SHIFTS AND TOUGHER BLOB WALLS (R53)","lines":[["b","Options in tabs. SOUND, VIDEO, PLAY, SHIP and MORE. Flip tabs with L / R, or left /"],["b+","right on the tab row."],["b","Reality shifts in the levels. The fold now flips your view for you once or twice on"],["b+","every planet, not only in the last boss fight. Where it happens is random each run, but"],["b+","always somewhere in the middle half of the level and never right on a change of view."],["b+","Roll back yourself."],["b","The last boss's blob walls hold. They have more than ten times the health and scale with"],["b+","your guns, so it now takes a few seconds of focused fire to burst one before it reaches"],["b+","you."],"",["img","shots/options-tabs.jpg","OPTIONS SPLIT INTO TABS",560,420]]},{"title":"46. CUTSCENES BETWEEN PLANETS (R54)","lines":[["b","A short flight between planets. After each boss, before the map and hyperspace, there is"],["b+","a short scene. The world you saved slides away behind you, the next one looms up with"],["b+","the rift cracked across it, and you fly with RIVET-9 tucked in behind. He talks you"],["b+","through it on comms, with his face doing the acting: proud, then panicking, then fired"],["b+","up."],["b","RIVET-9 calls the reality shifts in the levels and in the last boss fight, with a WHOA"],["b+","WHOA WHOA! and a shocked face."],"",["img","shots/cutscene-mars.jpg","LEAVING EARTH FOR MARS, WITH RIVET-9 ON COMMS",560,315]]},{"title":"47. A STORY BETWEEN THE PLANETS (R55)","lines":[["p","The cutscenes now tell a story, five lines each, and it carries through to the ending:"],["b","Earth to Mars. RIVET-9 used to work for OVERSEER (he was its spellchecker). Before it"],["b+","crashed it sent one word to Mars: WAKE. The stone heads there are not statues. They are"],["b+","antennas the Fold listens through."],["b","Mars to Jupiter. THE COLOSSUS talked on the way down: the Fold cannot see depth and only"],["b+","ever sees one side at a time. That is why it hates a pilot who sees all four. So it grew"],["b+","an eye inside Jupiter."],["b","Jupiter to Planet X. RIVET-9 pulls coordinates out of the Eye's last look. Planet X is"],["b+","not a planet. It is a dream that something far past Pluto is having, and the only hope"],["b+","is to break the dream so the dreamer stays asleep."],["b","The ending's last line now points back at the dreamer. Each line also stays on screen"],["b+","longer, so the whole thing can be read and heard."],"",["img","shots/cutscene-x.jpg","ON THE WAY TO PLANET X",560,315]]},{"title":"48. A JAM BANNER ON THE TITLE SCREEN (R56)","lines":[["b","The Game Off note on the title screen is now a neon pennant hanging in the top right"],["b+","corner: GITHUB GAME OFF 2026, THEME: SHIFT and a DEVLOG button. It sways, glints and"],["b+","glows brighter when you point at it. Click or tap it, or press the drone button, to read"],["b+","the devlog. The DEVLOG item has left the title menu."]]},{"title":"49. SKIN PREVIEWS (R57)","lines":[["b","The SHIP tab in Options now shows the skin you are looking at as a turning model, with"],["b+","dots for all four skins. A skin you have not earned is a dim silhouette with a padlock,"],["b+","plus what unlocks it: beat the boss, or the Sparkz price from the store (FIRE MAGE: THE"],["b+","COLOSSUS or 500, PIXIE: THE EYE or 650, DARK LORD: THE SHIFTER or 800)."],"",["img","shots/skin-card-fire-mage.jpg","A SKIN YOU HAVE UNLOCKED, TURNING IN THE PREVIEW",560,420],"",["img","shots/skin-card-locked.jpg","A LOCKED SKIN: A DIM SILHOUETTE, A PADLOCK AND WHAT UNLOCKS IT",560,420]]},{"title":"50. SKINS DROP FROM THE WARP STAGES (R58)","lines":[["b","A reason to find the warps. Skins no longer come from the main bosses. Each one drops"],["b+","from the miniboss of a hidden warp stage: FIRE MAGE from SOLAR FLARE on the Sun (warp on"],["b+","Mars), PIXIE from THE MOTHER ROCK in the Asteroid Belt (warp on Jupiter), DARK LORD from"],["b+","FROST WARDEN on Pluto (warp on Planet X). You can still buy them with Sparkz."],["b","The music slider works. Each sound bus used to go into one shared compressor that evened"],["b+","the volume back out, so turning the music down barely changed anything. Music and sound"],["b+","effects now each have their own compressor, the sliders come after it, and a limiter at"],["b+","the very end only catches peaks."],["b","SHIP is the first options tab."]]},{"title":"51. A CLEANER, SMOOTHER TITLE SCREEN (R59)","lines":[["b","Smooth title. No game plays behind the title any more. The backdrop is now a slow"],["b+","starfield over a rolling neon grid floor, with a pink glow on the horizon, and it costs"],["b+","almost nothing to draw. In a test it went from about 15 to 55 frames a second."],["b","New layout. Your ship turns in the middle of the screen in the skin you have equipped,"],["b+","and the menu sits under it in two centred rows."],["b","BUG TEST has moved out of the title and pause menus into Options, on the MORE tab."],["b","The title voice says the whole name again. In some browsers a line spoken straight after"],["b+","another one was cut gets dropped, so the 2DISO part was being lost and only a rushed"],["b+","SHIFT came through. The title is now one slower line with a real pause in the middle."],"",["img","shots/title-r59.jpg","THE NEW TITLE SCREEN",560,315]]},{"title":"52. A DEVLOG YOU CAN ACTUALLY READ (R60)","lines":[["b","Entries fold up. The in-game devlog used to be one long wall of text. Now every entry is"],["b+","a single line until you open it, and only one is open at a time. Tabs along the top"],["b+","split it into the backstory, each day of the jam and the to-do list, and the screenshots"],["b+","from this page appear inside the entries they belong to."],["b","The DEVLOG button is back on the title menu, on the second row between ACHIEVEMENTS and"],["b+","EXIT. The jam banner in the corner is now just a banner."],"",["img","shots/devlog-tabs.jpg","DAY 3 IN THE NEW DEVLOG, EVERY ENTRY FOLDED TO ONE LINE",560,315],"",["img","shots/devlog-entry-open.jpg","AN ENTRY OPENED, WITH ITS SCREENSHOT INSIDE",560,315],"",["img","shots/title-devlog-button.jpg","THE DEVLOG BUTTON BACK ON THE TITLE MENU",560,315]]},{"title":"53. ICE, LAND AND BETTER CRAWLERS (R61)","lines":[["b","Pluto rebuilt. It was the dullest stage. Now the ice shelf has icicles hanging over it,"],["b+","the chase stretch throws snowflake comets at you (six-armed flakes with long icy tails)"],["b+","between cryo geysers that blast columns of ice crystals, icicles hang from above and"],["b+","spikes grow from below, and the last stretch is a field of drifting icebergs in iso"],["b+","view. Snow falls the whole way."],["b","No more boxes round spikes. Rock spikes and icicles used to sit inside a shaded box that"],["b+","ran right up the point. They are now filled face by face as cones."],["b","Eruptions without the glitch. Lava geysers, in the level and in THE COLOSSUS fight, used"],["b+","to flash a box while they built up and stand in a box once they blew. Now a ghostly"],["b+","column of rising rings marks where one is about to go, and the eruption is just fire."],["b","Crawlers. The ground walkers were a ball on four sticks. Now they are six-legged"],["b+","armoured mech crabs with a domed shell, a red eye that tracks you and twin guns,"],["b+","stepping in two sets of three. They are a bit bigger and turn up more often, in pairs."],["b","Earth stands on land. The city floor used to be a grid over open space with stars"],["b+","showing through. Now it is solid ground: an asphalt road with kerbs, lane lines and"],["b+","zebra crossings, and street lamps along both pavements."],"",["img","shots/pluto-icicles.jpg","PLUTO: ICICLES, CRYO GEYSERS AND SPIRES IN CHASE VIEW",560,315],"",["img","shots/earth-streets.jpg","EARTH ON SOLID GROUND, WITH LANE LINES AND STREET LAMPS",560,315],"",["img","shots/mars-geyser-plumes.jpg","MARS LAVA GEYSERS, JUST FIRE NOW",560,315],"",["img","shots/crawlers.jpg","THE NEW CRAWLERS",560,315]]},{"title":"54. BLOB WALLS YOU CAN READ (R62)","lines":[["b","THE SHIFTER's blob walls cycle through the rainbow, flash solid red every time you hit"],["b+","them, and carry a health bar that goes from green to yellow to red. The red and the bar"],["b+","keep their true colours even on the trippy planet, where everything else shifts hue."],"",["img","shots/blob-wall-rainbow.jpg","A BLOB WALL IN CHASE VIEW, AND THE SAME WALL FLASHING RED AS IT TAKES A HIT",560,158]]},{"title":"55. TOUGHER MINIBOSSES, A FULLER BUG TEST (R63)","lines":[["b","Warp-stage minibosses last. LUNAR SENTINEL, SOLAR FLARE, THE MOTHER ROCK and FROST"],["b+","WARDEN went down in about three seconds, too fast to see what they do. They now have"],["b+","four times the health: around 12 seconds with maxed guns and 15 to 20 with weak ones."],["b+","The arena champions get half again as much."],["b","Bug test: every boss on its own. The list now has all four bosses and all four"],["b+","warp-stage minibosses as separate entries. Each one drops you in just before the fight"],["b+","and ticks off when you win it."],["b","Bug test: no warps. Bug test runs of the planets no longer spawn warps, so you can't fly"],["b+","into one by accident and leave the level you are testing."]]},{"title":"56. ROOM TO FIGHT (R64)","lines":[["b","Warp-stage minibosses used to park close in front of you, leaving little room to back"],["b+","off. They now come in from further away and hold well up the lane, so there is space to"],["b+","dodge and fight."],["b","The pop-up cards in the corner grow to fit their text. A long one, like the tick for the"],["b+","MOTHER ROCK test, used to spill out of its card."],["b","On the Sun the heat meter drops below a boss or miniboss health bar instead of sitting"],["b+","on top of it."]]},{"title":"57. SMOOTH FIRST: GRAPHICS SETTINGS AND DYNAMIC FRAMERATE (R65)","lines":[["p","A proper look at where the time goes. The answer was clear: the game logic costs almost"],["p+","nothing (about a quarter of a millisecond a frame). Nearly all of a frame is spent painting"],["p+","glowing lines, and the cost grows with how many pixels there are and how many times each"],["p+","line is painted."],"",["b","GRAPHICS: HIGH / NORMAL / LOW in Options, VIDEO tab. HIGH is the full look. NORMAL keeps"],["b+","the glow but softer, at three quarters of the resolution. LOW has no glow, half the"],["b+","resolution and no far skyline it is plain but sharp and readable."],["b","DYNAMIC FRAMERATE (on by default). It watches the frame time while you play. If frames"],["b+","run long it drops a step within a second, faster if things are really bad, and climbs"],["b+","back after ten smooth seconds. If it climbs and has to drop again straight away, it"],["b+","waits twice as long before the next try, so it does not bounce. There is one emergency"],["b+","step below LOW that only this can reach. The option shows the step it is on."],["b","Cheaper glow at every setting. The halo round each line used to be painted twice at full"],["b+","size. Now the glow is painted once into a small off-screen buffer and laid over the"],["b+","picture, and the wide outer halo is that same buffer shrunk and stretched. It looks the"],["b+","same and takes one pass fewer per colour."],["b","Cheaper text on the lower settings: the neon halo on HUD text goes first."],"",["p","On a test machine with no graphics card at 1080p, the same Mars stretch went from 29 frames"],["p+","a second on HIGH to 44 to 48 with dynamic framerate on."]]},{"title":"58. EVERYTHING GOES THROUGH RIVET-9 (R66)","lines":[["b","No more centre-screen banners. Sector names, waves, minibosses, boss kills, LAVA RISING"],["b+","and the rest now all arrive in RIVET-9's comms window, each with its own opener and face"],["b+","(HERE WE GO!, INCOMING!, UH OH!, YES!!)."],["b","Flashing status warnings moved there too: overheating, flying over lava, a shielded boss"],["b+","core, leaving the clear channel on the Sun and the arena's view call. He says each one"],["b+","once when it starts instead of it flashing in the middle of the screen. The gauges keep"],["b+","a short plain label."],["b","The heat meter no longer sits on top of the level progress bar."]]},{"title":"59. CLARITY MODE (R67)","lines":[["b","A new CLARITY switch under VIDEO for when the screen gets busy. The backdrop dims, your"],["b+","own shots, beams and explosions turn translucent, particles and score pops are capped,"],["b+","and enemy bullets always draw on top with a dark backing so they stay readable through"],["b+","everything."],["b","Left: normal. Right: clarity on. Top is the Mars boss in TOP view, bottom is Planet X in"],["b+","SIDE view."],"",["img","shots/clarity-before-after.jpg","CLARITY OFF (LEFT) AND ON (RIGHT)",560,315]]},{"title":"60. SIX RANKS FOR EVERYTHING (R67)","lines":[["b","Every weapon, the shield, the bomb and the hyperdrive now have six ranks, the same as"],["b+","drones. The old top ranks are still the top the new ones in between each add a twist"],["b+","instead of just more damage."],["b","MISSILE: Sparkler, Swarm, Shrapnel (hits throw shards), Barrage, Tagger (marked enemies"],["b+","take more damage), Cluster."],["b","LASER: Penlight, Focus, Mirror (the beam eats bullets), Lance, Capacitor (every fifth"],["b+","pulse hits hard), Prism."],["b","WAVE: Ripple, Wide, Echo (a mirrored second wave), Tidal, Undertow (shoves enemies"],["b+","back), Tsunami."],["b","BOLT: Static, Fork, Magnet Coil (pulls pods in), Chain, Blackout (clears nearby"],["b+","bullets), Storm."],["b","SPREAD: Double Tap, Twin Fan, Piercer, Star Fan, Railgun, Nova Fan."],["b","SHIELD: Film, Barrier, Blowback (losing a layer knocks bullets away), Double Barrier,"],["b+","Afterglow (longer safe time after a hit), Triple Barrier."],["b","BOMB: Wide Ring, Sweep Bomb, Backdraft (a second sweep), Scatter Bomb, Vacuum (pulls in"],["b+","every pod), Mega Nuke."],["b","HYPERDRIVE still unlocks only once everything else is maxed: Overclock, Magnet,"],["b+","Quicksilver (faster fire), Second Wind (one free save per level), Bomb Forge (bombs"],["b+","refill slowly), Singularity."]]},{"title":"61. SMALL FIXES (R67)","lines":[["b","God mode and overdrive countdowns now live in RIVET-9's comms window instead of the"],["b+","middle of the screen."],["b","Once everything is maxed, pickups stop being upgrade pods. You get the odd bomb, or"],["b+","points."]]},{"title":"62. THE LABYRINTH, AND TIGHTER PACING (R68)","lines":[["b","Mars has a new stretch between the caves and the magma tubes: THE LABYRINTH, a maze of"],["b+","lava rock seen from above. The forge locks your speed at SLOW the whole way through. One"],["b+","gap in each row is the way on. The other gaps lead into side pockets with gems and pods,"],["b+","sealed at the far end by rock you have to blast through."],["b","Earth was the longest level by a wide margin, so parts of the skyscrapers, skyways and"],["b+","firewall gates are gone. The construction zone and the hover traffic stay in full."],["b","Warp stages are shorter: the run up to each miniboss is trimmed, and the minibosses keep"],["b+","their full health. Bonus arenas have smaller waves, so each one takes about a minute."],["b","The blob walls in the final boss fight have a bit less health."],"",["img","shots/mars-labyrinth.jpg","THE LABYRINTH ON MARS",560,315]]},{"title":"63. THE MOTHERLODE (R69)","lines":[["b","Halfway through the asteroid belt you now fly into one giant hollowed-out rock with a"],["b+","mining colony inside it, played in SIDE view. The cave roof and floor close in, drill"],["b+","rigs pump up and down, ore carts run along the rails, laser fences guard the seams and"],["b+","the ore crates are full of gems. Mining drones patrol it. After that you're back out"],["b+","among the rocks."],"",["img","shots/belt-motherlode.jpg","THE MOTHERLODE",560,315]]},{"title":"64. THE STAGE MOVES (R70)","lines":[["b","Planet X already rocked the screen a little. Now the whole stage turns, tips, rolls and"],["b+","drifts in many more places, and the controls stay screen-relative: up on the stick is"],["b+","always up on the screen, however the stage is turned."],["b","Jupiter has a new stretch, THE DESCENT. The deck gives way and the stage turns on its"],["b+","side, so you fall straight down through Jupiter's coloured gas bands, threading gaps in"],["b+","the cloud shelves and lightning, until the storm opens into the sea below. A little of"],["b+","the lightning chains and storm walls came out to make room, so the level is about the"],["b+","same length."],["b","Mars: the magma tubes roll all the way round as you fly through them."],["b","Planet X: the fold flips the membranes section upside down, the tentacle forest heaves,"],["b+","and the gullet twists as it carries you along."],["b","Earth: the street banks and weaves through the hover traffic."],["b","Warp stages: the Moon trench floats about in the low gravity, the Sun's channel tips"],["b+","nose-down for the dive, and the Pluto blizzard rocks the stage."],["b","Bosses always fight on a level stage."],["b","Fixed a bug in the level trimming from r68/r69: scenery after a trimmed stretch stayed"],["b+","where it was instead of moving up with the rest."],"",["img","shots/jupiter-descent.jpg","THE DESCENT ON JUPITER",560,315],"",["img","shots/sun-dive-tilt.jpg","THE SUN'S DIVE, TIPPED NOSE-DOWN",560,315]]},{"title":"65. SMOOTH FROM THE FIRST SECOND (R71)","lines":[["b","New players now start on NORMAL graphics with dynamic framerate on, on every device."],["b+","HIGH is still one tap away in VIDEO."],["b","New RESET TO DEFAULTS under OPTIONS > MORE. Press it twice to confirm. Your chosen ship"],["b+","skin stays."],["b","Before the playtest: a full sweep through every level, warp stage, arena and boss at"],["b+","every graphics setting, with clarity on and off, plus every menu. Nothing broke."]]},{"title":"66. THE PICTURE BREAKS UP (R72)","lines":[["b","A glitch effect, like an old TV giving out: torn lines, the picture slipping, red and"],["b+","blue splitting apart, static and a rolling band."],["b","It hits just before a reality shift throws you into another view, briefly when a shield"],["b+","layer pops, and hard when you lose a ship."],["b","On your last ship with no shield left, the screen starts to glitch on its own, and more"],["b+","often the longer you stay like that. Pick up a shield and it calms down."],["b","The Shifter attacks the screen itself: between its shells, now and then mid-fight, and"],["b+","in one big burst of static as it dies."],["b","Invisible wraiths on Jupiter fuzz the signal when they get close."],["b","Turning SCREEN SHAKE off tones the glitch right down."],["b","The shield layers around the ship are spaced further apart and only the inner one glows,"],["b+","so you can count them."],"",["img","shots/glitch.jpg","GLITCH",560,315]]},{"title":"67. SHH-SHH-SHIFT (R73)","lines":[["b","On the title screen the announcer now says '2diso', then a stuttering SHIFT that echoes"],["b+","away, softer and quicker each time, with a faint electronic ping under each echo."],["b","The ship swooping in at the end of the intro has a sound now: air building to a roar as"],["b+","it comes at you, then a falling doppler as it peels away."],["b","Fixed the old drawn GRiDDiM splash flashing up for a moment before the real logo: the"],["b+","intro now shows nothing until the logo image has loaded, and it waits by the clock"],["b+","instead of counting frames, which ran out early on fast monitors."]]},{"title":"68. SPLASH SOUNDS AND TWO VOICES (R74)","lines":[["b","The GRiDDiM splash hums and crackles like a neon sign powering up."],["b","The ArcadeGridz splash plays a couple of bars of chiptune, finishing on a bright chord."],["b","The ship's swoop sound starts a little earlier."],["b","The title line is now two voices: a female voice says '2diso', then a male voice"],["b+","stutters 'shif, shif, SHIFT!' and echoes away. The voices are picked once the browser"],["b+","has its full voice list, so the first line no longer falls back to the default voice."]]},{"title":"69. TIDYING THE TITLE (R75)","lines":[["b","The text on the jam ribbon is sized to fit inside its dashed border."],["b","The stutter is now 'Sh, Sh, SHIFT!', and it and its echoes are spoken faster."],["b","Any real click, tap or key press anywhere on the page now switches the sound on."],["b+","Browsers keep a page silent until you interact with it, and some clicks were not getting"],["b+","through to wake the music."]]},{"title":"70. QUIETER LAUNCH (R76)","lines":[["b","The title line is now just a female '2diso', then a male 'SHIFT!' echoing away. The"],["b+","stutter is gone: the browser voice kept spelling it out letter by letter."],["b","The game's own sound now waits about a second after launch before starting, so the"],["b+","ArcadeGridz app's coin-drop sound isn't cut off."]]}]},{"name":"TO DO","entries":[{"title":"WHAT IS LEFT TO DO","lines":[["b","Hardware testing: a controller in the ag app, phones, tablets."],["b","Balance by hand. The autopilot clears everything people are not autopilots."],["b","Finish the bug test list, then hide the bug test menu for the jam build."],["b","Recorded announcer lines instead of the browser voice."],["b","Push the HTML5 build to itch.io (the page is set up as a draft) and submit it to the"],["b+","jam."],["b","Retake the itch.io screenshots once the game is final."]]}]}];
export const CREDITS = [['h1','2DISO SHIFT'],'',['h3','GAME DESIGN AND DIRECTION'],['p','BENJAMIN CAMPBELL (BDC)'],'',['h3','PROGRAMMING, VECTOR ART, SOUND'],['p','CLAUDE (ANTHROPIC), DIRECTED BY BDC'],'',['h3','BASED ON'],['p','2DISO, THE ORIGINAL GAMEMAKER GAME BY BDC / SYCX1'],'',['h3','MADE FOR'],['p','GITHUB GAME OFF 2026 - THEME: SHIFT'],'',['h3','TECH'],['p','PLAIN JAVASCRIPT. CANVAS 2D AND WEB AUDIO.'],['p','NO ENGINE, NO ART FILES, NO AUDIO FILES.'],'',['h3','THANKS'],['p','EVERYONE ON THE GRIDDIM NETWORK'],'',['q','(C) 2026 GRIDDIM / ARCADEGRIDZ / BDC'],['p','CODE RELEASED UNDER THE MIT LICENSE']];
